pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post-placement residual (Best-Fit approach)
    let mut score = post;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize values below the expected mean of the remaining stream (modeled as 35).
    if post > 0.0 && post < 35.0 {
        score += (35.0 - post).powf(1.5);
    }

    // Lookahead logic: If the next item fits into the post_residual, reward this bin.
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= 25.0 * (1.0 - progress);
    }

    // New Bin Logic: If we are opening a new bin (bin_residual == bin_capacity), 
    // only do so if the current open bins are very full (low mean_residual).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 100.0; // Heavily penalize opening new bins if existing ones have space
        } else {
            score -= 5.0; // Slightly favor new bin if current ones are nearly full
        }
    }

    // Fitting Bins logic: If this is the only bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 50.0;
    }

    // Dynamic scaling based on stream progression: 
    // As the stream ends, become more aggressive about filling bins (Best-Fit).
    score += (progress * 20.0) * (post / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing
    // We scale this by a non-linear factor to prefer tighter fits late in the process.
    score += (post_residual as f64).powf(1.5) * (1.0 + progress);

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // we reward this placement heavily to encourage "pairing" items.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 25.0;
    }

    // 3. Fragmentation Avoidance: If the post_residual is small but > 0, it creates "dead space"
    // that is likely unusable for future items (typically < 10).
    if post_residual > 0 && post_residual < 15 {
        score += 40.0 * (1.0 - progress);
    }

    // 4. Global State Pressure: If we have many open bins, penalize opening a new one.
    // If bin_residual == bin_capacity, we are evaluating opening a NEW bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Heavily penalize opening new bins when existing capacity is available
            score += 150.0 * (1.0 - (fitting_bins_count as f64 / (open_bins_count as f64 + 1.0)));
        }
    } else {
        // 5. Mean Residual Balancing: If the current bin is significantly less efficient
        // than the average, we penalize it to keep the "good" bins available.
        if (bin_residual as f64) < mean_residual {
            score += 10.0;
        }
    }

    // 6. Final Fit-Force: If this is the only bin that can fit the item, 
    // we force-accept it by reducing the score significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but not zero (fragmentation).
    // If post_residual is in [1, 15], it's likely "dead space".
    if post_residual > 0 && post_residual < 16 {
        score += 40.0 * (16.0 - post_residual as f64);
    }

    // 2. Lookahead Synergy: If next_item_size fits in the post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 50.0;
        // Further reward perfect fit for next item
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the remaining space is 
    // highly inefficient for the current distribution.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many bins and the current mean residual is low,
        // or if we have no good choices (fitting_bins_count is low).
        score += 15.0; 
        if fitting_bins_count > 0 {
            score += 60.0; 
        }
    }

    // 4. Density Balancing: If we are late in the stream, favor filling existing bins 
    // to minimize the total count (packing density).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.7 {
        score -= (1.0 - progress) * 20.0;
    }

    // 5. Harmonic Class Logic: Favor bins that leave a residual which is a multiple of 
    // common item sizes (e.g., 20, 25, 50) to allow future packing.
    if post_residual > 0 {
        let remainder = post_residual % 20;
        if remainder == 0 {
            score -= 10.0;
        } else if remainder > 15 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space: we prefer smaller post-residual (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": if the post-residual is too small to fit the 
    // average item size, it's effectively wasted. We use mean_residual as a proxy for 
    // bin state density.
    if post_res > 0.0 && post_res < mean_residual {
        score += 15.0 * (1.0 - (post_res / mean_residual));
    }

    // Lookahead logic: if the next item is large, penalize small residuals that 
    // would force a new bin later.
    if next_item_size > 0 {
        let lookahead_penalty = (next_item_size as f64 - post_res).max(0.0);
        score += lookahead_penalty * (1.0 - progress);
    }

    // Strategy shift: Early in the stream, favor tight packing. 
    // Late in the stream, be more aggressive to consolidate bins to avoid opening new ones.
    if fitting_bins_count == 1 && post_res > 5.0 {
        score += 20.0 * (1.0 - progress);
    }

    // Normalize empty bin selection: If this is an empty bin, its score is the capacity.
    // We apply a non-linear cost to opening new bins that increases as the stream progresses.
    if bin_residual == bin_capacity {
        score = 25.0 + (30.0 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "fragmented" space that is likely too small for future items
    // We target residuals that are multiples of common item sizes (harmonic clustering)
    if post_residual > 0 && post_residual < 20 {
        score += 50.0;
    }

    // Heuristic: If this is the last fitting bin, penalize the new-bin option heavily
    // unless the fit is extremely poor (post_residual is small)
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 45.0;
    }

    // Lookahead logic: If the next item fits into the post_residual, reward this bin choice
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Harmonic alignment: Reward residuals that match the mean_residual of current bins
    // to keep bin fill levels consistent (minimizing variance)
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // Progression awareness: As we reach the end of the stream, prioritize tightest fit
    // to minimize the number of open bins left behind
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    // Penalize creating new bins (bin_residual == bin_capacity) if we have many bins already
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "slivers": gaps smaller than the minimum likely item (approx 10)
    // are often dead space. We penalize post_residual ranges [1, 9].
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // Heuristic: If we have many open bins, prioritize filling the tightest fitting one (Best-Fit).
    // If we have few open bins, prioritize keeping residuals large to accommodate future items.
    if open_bins_count > 0 {
        let density_factor = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score += (open_bins_count as f64) * density_factor * 5.0;
    }

    // Lookahead logic: If the next item can fit in the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // New Bin Penalty: If this is a new bin (residual == capacity), penalize it 
    // heavily unless fitting_bins_count is 0 (i.e., we have no choice).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            score -= 10.0; // Encourage opening a new bin if nothing else fits
        }
    }

    // Pressure to keep open_bins_count low as we approach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Best-Fit logic: prioritize smaller post_residual (tightest fit)
    // We normalize this by the bin capacity to keep the scale consistent.
    score += (post_residual as f64) * 0.5;

    // 2. Harmonic Class Logic: penalize bins that leave "awkward" remainders.
    // If post_residual is small but not zero, it might block future large items.
    // We penalize remainders that are smaller than the next item size but large enough to be wasted.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 2.5;
    }

    // 3. Penalty for fragmentation:
    // If we have many open bins, we want to consolidate.
    // If post_residual is high, we penalize it more when open_bins_count is high.
    score += (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // 4. Thresholding for "New Bin" creation:
    // If bin_residual == bin_capacity, this is a new bin. 
    // We only want to open a new bin if fitting_bins_count is low or if current fits are terrible.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // Must open a new bin, set score very low.
            score = -100.0;
        } else {
            // Opening a new bin is expensive; penalize unless the fitting bins are very poor.
            score = 50.0 + (mean_residual * 0.5);
        }
    } else {
        // 5. Harmonic packing: favor bins that result in multiples of common item sizes (e.g., 20, 25, 33).
        // Penalize remainders that are prime or "difficult" numbers.
        let remainder_mod = post_residual % 10;
        if remainder_mod == 0 {
            score -= 5.0; // Encourages "clean" bin states
        } else if remainder_mod > 5 {
            score += 3.0; // Penalize "dirty" bin states
        }
    }

    // 6. Progression bias:
    // As we approach the end of the stream, be more aggressive with packing (less picky).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": gaps smaller than the minimum likely item size (10)
    // are extremely hard to fill later. We penalize post_residuals in the (0, 10) range heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Lookahead logic: if the next item could fit into this post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Pressure management: If we are forced to open a new bin, penalize the new bin 
    // unless the mean_residual of existing bins is already very low (indicating we are packing tightly).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 15.0 + (mean_residual * 0.5);
        }
    } else {
        // Favor bins that are already open to keep open_bins_count low, 
        // but penalize bins that are becoming too sparse (mean_residual logic).
        score += (open_bins_count as f64) * 0.5;

        // If this is the only bin that can fit the item, give it a significant priority boost
        // to prevent opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Progression scaling: As the stream nears completion, prioritize closing bins (lower residuals)
    // even at the cost of slight fragmentation.
    let progress = step_index as f64 / total_items as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating a bin that is too fragmented to be useful for future average items
    // If post_residual is small but > 0, it is often a "dead zone".
    if post_residual > 0 && post_residual < 20 {
        score += 45.0;
    }

    // Lookahead logic: if the current item leaves space for the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Further reward if it creates a perfect or near-perfect fit for the next item
        if (post_residual - next_item_size) < 5 {
            score -= 20.0;
        }
    }

    // Heuristic for new bin allocation: 
    // If we are forced to open a new bin (fitting_bins_count == 0), 
    // ensure we don't penalize it excessively compared to bad fits in existing bins.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Only open a new bin if the existing bins are highly fragmented (mean_residual is small)
            if mean_residual > 25.0 {
                score += 40.0; // Discourage opening new bins early
            } else {
                score -= 10.0; // Encourage opening if current bins are mostly full
            }
        }
    } else {
        // Prefer bins that bring the residual closer to the global mean residual
        // to keep bin utilization balanced.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Progress-based scaling: As the stream nears the end, be more aggressive with packing
    // to avoid leaving items stranded.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space avoidance: Penalize post_residuals that are too small to fit common items (10-25)
    // but too large to be considered "tight".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // Severe penalty: creating a 'sliver' that is likely unusable
    } else if post_residual >= 10 && post_residual < 20 {
        score += 20.0; // Moderate penalty: creating a gap that fits very few items
    }

    // 2. Lookahead optimization: If next item fits in this post_residual, reward this bin choice.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 3. Dynamic pressure: If fitting_bins_count is 1, we are at a "last chance" state.
    // If the post_residual is poor, we might prefer opening a new bin instead.
    if fitting_bins_count == 1 && post_residual > 15 {
        score += 15.0; // Slightly penalize the last-chance bin if it leaves a large gap
    }

    // 4. Global bin count control: Penalize opening too many bins as the stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 + progress * 5.0);

    // 5. If this is a new bin (bin_residual == bin_capacity), apply a baseline cost.
    // We only want to open a new bin if existing bins are poor fits.
    if bin_residual == bin_capacity {
        score = 45.0 + (progress * 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it often prevents fitting future items. We penalize mid-range residuals 
    // more heavily as the stream progresses to encourage consolidation.
    if post_residual > 0 {
        let dead_space_penalty = (100.0 - post_res).powf(1.5) * (1.0 + progress);
        score += dead_space_penalty;
    }

    // Lookahead coupling: if the next item is large, prioritize bins that 
    // leave enough room for it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Strong penalty for blocking the next item
            score += 200.0 * (1.0 - progress);
        }
    }

    // Efficiency bias: discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy 
    // penalty that decays as the stream progresses (late game: open new bins freely).
    if bin_residual == bin_capacity {
        score += 85.0 * (1.0 - progress.powi(2));
    }

    // Global consolidation: if we have many bins open, penalize placing items 
    // in bins that are far from the mean residual to encourage bin closure.
    let residual_variance = (post_res - mean_residual).abs();
    score += residual_variance * 0.5;

    // Critical threshold: if this is the only bin that fits, prioritize it 
    // heavily to avoid creating a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #631: Harmonic-Residual Balancing
    // We aim to minimize post_residual (Best Fit), but penalize "fragmentation" 
    // where the remaining space is too small for common future items.

    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: If post_residual is small (e.g., < 10), it is often 
    // unusable. Penalize these "dead-space" fragments heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, 
    // reward this placement to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Global Bin Management: If this is the last chance for the current item
    // (fitting_bins_count == 1), prioritize this bin to keep open_bins_count low.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // 4. Distributional Awareness: If we are late in the stream (high step_index),
    // become more aggressive in filling bins (Best Fit). If early, prioritize
    // leaving slightly larger gaps to accommodate future variance.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    } else {
        score += (mean_residual - post_residual as f64).abs() * 0.05;
    }

    // 5. New Bin Threshold: If we are considering a new bin (bin_residual == bin_capacity),
    // set a high cost unless open_bins_count is very low, to prevent premature bin opening.
    if bin_residual == bin_capacity {
        score += 40.0 - (open_bins_count as f64 * 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base cost: The remaining space (post_residual).
    let mut score = post_residual as f64;

    // 2. Penalty for creating "dead zones": if post_residual is small but not zero, 
    // it's likely to remain empty. We penalize values between 1 and 9.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead synergy: If the next item fits perfectly into the remaining space, 
    // we strongly prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward configurations where the next item fits with minimal slack.
        score -= (100.0 - diff) * 0.5;
    }

    // 4. Mean residual alignment: Avoid bins that deviate significantly from the 
    // average efficiency of the current packing state.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.1;

    // 5. New bin logic: If this is a new bin (bin_residual == bin_capacity), 
    // penalize opening it unless the current fitting options are extremely poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the 
