        score += 40.0;
        score -= (open_bins_count as f64) * 0.5;
    }

    // 6. Urgency: If this is the only bin that can fit the item, we shouldn't 
    // penalize it too heavily, even if the fit is mediocre.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
