        // average residual of other open bins to maintain a balanced packing distribution.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;

        // 5. Urgency: If this is the only bin that can fit the current item, 
        // prioritize it to prevent opening an unnecessary new bin.
        if fitting_bins_count == 1 {
