        }

        // Dynamic weight based on global state:
        // If mean_residual is high, we have many under-utilized bins, 
        // so prioritize filling existing bins even if the fit is suboptimal.
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // Constraint: Ensure we don't return negative scores that might break logic, 
    // though the relative ordering is what matters for the bin selection.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize the creation of a new bin (bin_residual == bin_capacity)
    // The penalty decreases as we reach the end of the stream to encourage packing density
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (50.0 + (1.0 - progress) * 150.0);

    // Non-linear coupling: penalize small remainders (fragmentation) 
    // but weigh it against the next item size to look ahead for better fits.
    // We want to avoid leaving residual space that is too small for common items.
    let fragmentation_penalty = if post_res > 0.0 && post_res < 15.0 {
        (15.0 - post_res) * 5.0
    } else {
        0.0
    };

    // Lookahead logic: if the next item fits into the current post_residual, 
    // reward this bin choice (lower score).
    let lookahead_bonus = if next_item_size > 0 && post_res >= next_item_size as f64 {
        (post_res - next_item_size as f64) * 0.5
    } else {
        0.0
    };

    // Global state awareness: penalize opening too many bins early on
    let open_bin_pressure = (open_bins_count as f64) * (1.0 + progress);

    // Final score assembly: Lower is better. 
    // We favor bins that minimize post_residual (Best Fit) but adjust for 
    // fragmenting space and lookahead potential.
    let mut score = post_res 
        + new_bin_penalty 
        + fragmentation_penalty 
        - lookahead_bonus 
        + open_bin_pressure;

    // Ensure we don't prefer a new bin over a perfect fit (post_res == 0)
    if is_new_bin > 0.0 && fitting_bins_count > 0 {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Harmonic classes logic.
    // Goal: Minimize fragmentation by balancing "Best Fit" with "Lookahead Compatibility".
    // We penalize residuals that are too small to fit common items (10-30 range)
    // and reward residuals that perfectly match the next_item_size (Perfect Fit).

    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: If post_residual is small but not zero, it's a "fragmentation trap".
    // Items are 10-80, so a residual < 10 is effectively dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If post_residual matches next_item_size, reward it heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
