    // 3. Global Density Balancing: If we have many open bins, penalize opening new ones.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is higher if we have many bins already open
        score += (open_bins_count as f64) * 5.0;
        // If we have fitting bins, discourage opening a new one unless it's a perfect match
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // 4. Mean Residual Normalization: Avoid creating bins that are significantly "emptier" than the average.
    if post_residual > mean_residual as u32 {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Progression scaling: As we approach the end of the stream, prioritize closing bins (tight fit).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    score
}

