    // We want to minimize post_residual, but we also want to avoid creating "slivers" (very small residuals)
    // if a future item (next_item_size) is unlikely to fit.
    let mut score = post * post;

    // Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        // If we are early in the stream, be more conservative about opening new bins.
        // As the stream progresses, allow new bins more easily to keep residuals high in existing ones.
