    }

    // Lookahead logic: If the next item is large, prioritize bins that can fit it.
    // If the current post_residual is too small for the next_item_size, penalize it slightly.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += 25.0 * (1.0 - progress);
    }

    // Encourage filling bins that are already "tight" compared to the mean
    if (bin_residual as f64) < mean_residual {
