    // 2. Harmonic Class Logic: penalize bins that leave "awkward" remainders.
    // If post_residual is small but not zero, it might block future large items.
    // We penalize remainders that are smaller than the next item size but large enough to be wasted.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 2.5;
    }

    // 3. Penalty for fragmentation:
    // If we have many open bins, we want to consolidate.
    // If post_residual is high, we penalize it more when open_bins_count is high.
    score += (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64) * 10.0;

