    // If bin_residual == bin_capacity, this is a new bin. 
    // We only want to open a new bin if fitting_bins_count is low or if current fits are terrible.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // Must open a new bin, set score very low.
            score = -100.0;
        } else {
            // Opening a new bin is expensive; penalize unless the fitting bins are very poor.
            score = 50.0 + (mean_residual * 0.5);
        }
    } else {
        // 5. Harmonic packing: favor bins that result in multiples of common item sizes (e.g., 20, 25, 33).
        // Penalize remainders that are prime or "difficult" numbers.
        let remainder_mod = post_residual % 10;
        if remainder_mod == 0 {
            score -= 5.0; // Encourages "clean" bin states
        } else if remainder_mod > 5 {
            score += 3.0; // Penalize "dirty" bin states
        }
    }

    // 6. Progression bias:
    // As we approach the end of the stream, be more aggressive with packing (less picky).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
