    }

    // 5. Last Chance Logic: If this is the only bin that fits, we are forced to take it,
    // but if it's a very poor fit (high post_residual), we might prefer a new bin.
    if fitting_bins_count == 1 && post_residual > 40 {
        score += 30.0;
    }

    score
