        score += 15.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting Constraint: If this is the ONLY bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Mean residual equilibrium: Favor bins that keep the average residual 
    // close to the ideal half-capacity (50), preventing extreme variance.
    let dev = (post_residual as f64 - 50.0).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post-placement residual (Best Fit principle)
    let mut score = post_residual as f64;

    // If this is a new bin, penalize it heavily unless we are forced to use it.
    // We only open a new bin if the score is lower than existing bins.
    if is_new_bin {
        // Base penalty for opening a new bin is high, but reduce it 
        // as we approach the end of the stream to clear out remaining items.
        score = (bin_capacity as f64 * 0.75) + (1.0 - progress) * 50.0;

        // If no existing bin can fit the current item, lower the penalty to force opening.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Evaluate the 2-step lookahead: 
        // If the current placement leaves a gap that perfectly fits the next item, reward it.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                let diff = (post_residual - next_item_size) as f64;
                // Reward configurations where the gap is tight (near 0) for the next item
                score -= (100.0 - diff) * 0.5;
            } else {
                // Penalize if the current placement makes the next item impossible to fit
                score += 20.0;
            }
        }

        // Penalty for creating "dead space": if post_residual is small but > 0, 
        // it's often better to leave it slightly larger to accommodate future items 
        // or keep it very small to minimize waste.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0; // Penalty for sliver waste
        }

        // Encourage balancing: if this bin's residual is much higher than the mean, 
        // prioritize filling it to keep the mean residual low.
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize tiny residuals that create "dead space" (e.g., < 10)
    // unless it fits perfectly (post_residual == 0).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Integration: If the next item can fit in the current post_residual,
    // lower the score (reward this bin).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 3. Global State Awareness: If we have many open bins, penalize opening a new one
    // or picking a bin that pushes the average residual too high.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have plenty of open ones.
        score += (open_bins_count as f64) * 5.0;
        // Dampen the penalty as we approach the end of the item stream.
        score -= (progress * 20.0);
    }

    // 4. Fitting Pressure: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Residual Balancing: If the post_residual is significantly higher than the 
    // mean residual of other bins, penalize it to keep bins "packed" similarly.
    if (post_residual as f64) > (mean_residual + 10.0) {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post;

    // Penalty for creating a bin that is too small for future items (dead space)
    // We penalize the post_residual if it's smaller than the next item
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 1.5;
    }

    // Dynamic pressure: As the stream progresses, favor tighter packing (lower post_residual)
    // We penalize larger post_residuals more heavily as we approach the end of the stream
    score += (post * progress) * 2.0;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy threshold penalty
    // to discourage opening new bins unless the fit in existing bins is truly abysmal.
    if bin_residual == bin_capacity {
        // We only open a new bin if the current 'best' fit is extremely poor
        // We set the threshold based on the mean residual of currently open bins
        score += 35.0 + (mean_residual * 0.5);
    } else {
        // Reward bins that have a residual close to the mean to consolidate usage
        let diff_from_mean = (post - mean_residual).abs();
        score -= diff_from_mean * 0.2;
    }

    // If this is the last chance for this item (only 1 fitting bin), 
    // heavily reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Harmonic-weighted Best-Fit with Lookahead Penalty.
    // We aim to minimize the post_residual, but heavily penalize "sliver" residuals
    // that are too small to fit common future items.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Harmonic penalty: Penalize residuals that are non-zero but too small to be useful.
    // Small residuals (1..9) are "dead space" traps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize this bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // 3. Pressure management: If we have many open bins, prioritize tightening existing ones.
    // If we have few open bins, be slightly more conservative about closing off space.
    if open_bins_count > 5 {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // 4. New bin thresholding: Make opening a new bin expensive unless the fit is truly poor.
    // Only open a new bin if the best existing fit is extremely inefficient.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Significant penalty for opening a new bin when space exists.
            score += 45.0;
        } else {
            // No existing bins fit, prioritize this new bin.
            score = 0.0;
        }
    }

    // 5. Progression scaling: As we approach the end of the stream, prioritize 
    // filling bins to capacity to avoid leaving stragglers.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
