    // We heavily penalize post_residuals that are small but non-zero.
    let dead_space_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post).powi(3) * 5.0
    } else {
        0.0
    };

    // Reward fitting the item into a bin that stays closer to the global mean residual
    // to keep the bin usage balanced.
    let balance_penalty = (post - mean_residual).abs() * 0.5;

    // Lookahead: If next_item_size is large, favor bins that have enough space to fit it.
    // If post_residual < next_item_size, we penalize the bin (unless it's the only one).
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.0
    } else {
        0.0
    };

    // Progress-sensitive weighting: Towards the end of the stream, 
    // prioritize filling existing bins (Best Fit Decreasing dynamic)
    // by squaring the post_residual to favor tightest fits.
    let base_score = if progress > 0.8 {
        post.powi(2)
    } else {
