    // If bin_residual == bin_capacity, we are evaluating a NEW bin.
    // Penalize opening a new bin unless the existing bins are quite full.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            // Existing bins have significant space, penalize opening a new one
            score += 60.0;
        } else {
            // Existing bins are tight, opening a new one is acceptable
            score += 15.0;
        }
    }

    // 5. Progression scaling:
    // As we approach the end of the stream, prioritize clearing remaining capacity
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score is the post_residual (Best Fit logic)
    let mut score = post_residual as f64;

    // Penalty for creating "dead space" (gaps too small for any likely future item)
    // Assuming 10 is the minimum item size, any residual < 10 is effectively wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is too small to fit the next item, penalize it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Pressure to consolidate: penalize opening new bins unless the current fit is extremely poor.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy opening cost.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.5);
    }

    // If this is the last fitting bin, prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Favor bins that align with the global mean residual to keep bin states uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // Start with the post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin prematurely:
    // If this is an empty bin (bin_residual == bin_capacity), penalize based on 
    // how many other bins could have accepted the item.
    if bin_residual == bin_capacity {
        score += 40.0 + (fitting_bins_count as f64 * 15.0);
    }

    // 2. Lookahead matching:
    // If the next item fits perfectly into the remaining space, reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            // Reward bins that leave just enough room for the next item, 
            // but punish bins that leave a tiny, unusable sliver.
            let wasted_gap = post_residual - next_item_size;
            if wasted_gap < 10 {
                score += 20.0; // Penalty for fragmentation
            }
        }
    }

    // 3. Balancing density:
    // If the post_residual is significantly lower than the mean_residual, 
    // we are packing tighter than average, which is desirable.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 4. Pressure management:
    // As the stream progresses, prioritize closing bins (lower residual) 
    // to consolidate space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
