    // Lower residual is generally better (Best Fit).
    let mut score = post;

    // Penalty for leaving a bin "nearly empty" or "unusable" (e.g., < 10)
    // We penalize very small residuals that are likely to become dead space.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 2.5;
