        // If there are other bins that could fit this item, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // Interaction with mean_residual: Prefer bins that are closer to the global average 
        // to keep bin utilization balanced.
        let dev = (post - mean_residual).abs();
        score += dev * 0.5;
    }

    // Encourage filling bins that are already "open" to minimize active bin count.
    score += (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize post_residuals that are small but non-zero (fragments)
    // We favor "perfect fits" (0) or "large residuals" (allowing future flexibility).
    if post_residual > 0 && post_residual < 20 {
        score += 45.0 / (post_residual as f64).sqrt();
    }

    // 2. Lookahead Logic: If the next item can fit in the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
