            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // We must open a new bin; normalize the score so it is selected.
            score = 5.0;
        }
    }

    // 5. Global Density Balancing: 
    // If the mean residual of current bins is high, we are "loose"; tighten by favoring smaller post_residuals.
    if mean_residual > 30.0 {
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
