        // This encourages "leveling" bins to keep them equally available for future items.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;

        // Lookahead adjustment: If the next item is large, penalize small post_residuals 
        // that would strand the next item.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 2.0;
            }
        }
    }

    // Heuristic pressure: If few bins can fit the current item, prioritize using the one 
    // that leaves the most flexible space (Best Fit) but avoid creating "dead zones" 
    // smaller than 10 (the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Favor bins that have higher open_bins_count utilization to keep active sets compact.
    score += (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We prioritize bins that leave a residual which is a multiple of common item sizes.
    let dead_space_penalty = if post_residual > 0 && post_residual < 20 {
        15.0 + (20.0 - post_residual as f64) * 2.5
    } else {
        0.0
    };

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is less than next_item_size, we penalize the current choice.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64 * 0.8
    } else {
        -5.0 // Reward: bin can accommodate the next item
    };

    // Harmonic class logic: minimize the "waste" relative to bin capacity.
    // We penalize bins that deviate significantly from the mean_residual of the system.
    let deviation_penalty = (post_residual as f64 - mean_residual).abs() * 0.5;

    // Strategic threshold: if this is the last fitting bin, we are desperate. 
    // We heavily discount the score to avoid opening a new bin prematurely.
    let desperation_bonus = if fitting_bins_count == 1 { -25.0 } else { 0.0 };

    // New-bin candidate handling: Ensure opening a new bin is expensive unless necessary.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        if open_bins_count == 0 { 0.0 } else { 45.0 }
    } else {
        0.0
    };

    score += dead_space_penalty + lookahead_penalty + deviation_penalty + desperation_bonus + new_bin_penalty;

    // Progress normalization: as we near the end of the stream, prioritize tight packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

