    score += (open_bins_count as f64) * 0.5;

    // Favor bins that align with the current mean residual to keep bin usage density balanced.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins packed tightly.
    // We weight this by the number of bins currently open to encourage consolidation.
    score += (post_residual as f64).powf(1.2) * (1.0 + (open_bins_count as f64 / 10.0));

    // 2. Lookahead Synergy (Archetype #103):
    // If the next item fits into the current post_residual, reward this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
