    // If this is a new bin (bin_residual == bin_capacity), penalize it unless no other bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one can accommodate the item.
            score += 85.0 + (open_bins_count as f64 * 2.0);
        } else {
            // No choice, must open new bin; normalize the cost.
            score -= 50.0;
        }
    }

    // 4. Mean Residual Balancing:
    // Avoid creating bins that are significantly "worse" than the current average.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Progression Weighting:
    // As we approach the end of the stream, prioritize closing bins (minimizing open_bins_count).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

