    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (a bin that is almost full but unusable).
    // Slivers are very difficult to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // reward this bin to keep the packing tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Dynamic thresholding based on the number of open bins.
    // If we have many open bins, we should be more selective to avoid fragmentation.
    if open_bins_count > 5 {
