    }

    // If this is the only bin that can fit the item, we are forced to take it.
    // We reduce the score to ensure it is prioritized over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New bin logic:
    // If the bin is brand new (residual == capacity), we only want to pick it if 
    // the current item is very large or if we have no good fits (high mean residual).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless item is large (e.g., > 70)
        // or we are nearing the end of the stream.
        score += 30.0;
        score -= (item_size as f64) * 0.3;
        score += (progress * 10.0);
    }

    // Encourage filling bins that are already closer to the mean residual of the system
    // to keep the distribution of bin usage uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space; we want to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for creating a "fragmented" bin: if the post_residual is small but not zero,
    // it is often harder to fill later. We penalize values in the (0, 15] range.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * 2.5;
    }

    // Lookahead logic: If the next item is large, we want to preserve space in current bins.
    // We penalize placing a small item into a bin if the next item is very large.
    if next_item_size > 0 {
        let lookahead_pressure = (next_item_size as f64 / bin_capacity as f64).powf(2.0);
        score += lookahead_pressure * (item_size as f64);
    }

    // Dynamic thresholding based on stream progress:
    // As the stream nears the end, we become more aggressive in packing bins to capacity
    // to avoid leaving trailing empty space.
    let tightness = (mean_residual / bin_capacity as f64).powf(1.5);
    score -= tightness * progress * 10.0;

    // If this is a new bin (bin_residual == bin_capacity), calculate the cost of opening it.
    // We only open a new bin if the current packing efficiency is low.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin early, decreasing as open_bins_count grows
        // or as we reach the end of the stream (where new bins might be inevitable).
        let open_cost = 25.0 + (progress * 15.0) - (open_bins_count as f64 * 0.5);
        score += open_cost;
    } else {
        // If it's an existing bin, reward bins that are already "near full" to consolidate.
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;
    }

    // Adjust for scarcity: if only one bin can fit the item, we are forced to use it.
    // This is handled by the selection logic, but we nudge the score to prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
