    let mut score = (post_res * progress_weight) + sliver_penalty + lookahead_penalty;

    // Heuristic for new bin: 
    // If this is an empty bin (bin_residual == capacity), we only want to open it
    // if all current open bins result in a very poor fit (large post_residual).
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low,
        // suggesting we are wasting space by forcing items into existing bins.
        // We set a threshold for opening a new bin based on the mean_residual.
        score = 35.0 + (mean_residual * 0.5);
    } else {
        // If it is the last chance for this item to fit, apply a discount
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize minimizing the post_residual (tightest fit).
    // Penalize large post_residuals exponentially.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead logic: if next_item_size is large, avoid small post_residuals.
    // If post_residual cannot fit the next item, penalize it.
    if next_item_size > 0 && post_residual < next_item_size {
