    // 3. Harmonic class awareness: 
    // Prefer bins that leave space for common divisors of capacity (e.g., 20, 25, 50).
    // Penalize post_residuals that are prime or "awkward" (e.g., 7, 13, 17).
    let rem = post_residual % 10;
    if rem == 0 {
        score -= 10.0;
    } else if rem > 7 {
        score += 5.0;
    }

    // 4. Global state pressure: 
    // If we have many open bins, be more aggressive at filling existing ones (higher penalty for new).
    // If fitting_bins_count is 1, it's a "last chance" for this bin; prioritize it.
    if bin_residual == bin_capacity {
        // New bin penalty: scales with the number of open bins and relative progress.
        let progress = step_index as f64 / total_items as f64;
        score += 25.0 + (open_bins_count as f64 * 2.0) + (progress * 15.0);
    } else {
        // Favor bins that are near the mean residual to keep bin levels balanced.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.5;

        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

