    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // Penalize small residuals that are likely to become "dead space" (e.g., < 10).
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
