    } else {
        0.0
    };

    // Lookahead logic: If the next item fits into the current post_residual, 
    // prioritize this bin heavily to keep packing density high.
    let lookahead_reward = if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        -25.0 * (1.0 - progress)
    } else {
