        // compared to forcing a tight fit into an existing bin.
        base_new_bin + (progress * 30.0)
    } else {
        0.0
    };

    // Density normalization:
    // Favor bins that align with the global mean residual to keep bin states uniform.
    let variance_penalty = (post - mean_residual).abs() * 0.5;

    // Combine components:
    // Lower score is better.
    post + dead_space_penalty + lookahead_reward + new_bin_cost + variance_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
