            // Reward bins that can accommodate the next item perfectly
            score -= (bin_capacity - (post_residual as i32 - next_item_size as i32).abs() as u32) as f64 * 0.5;
        } else {
            // Penalize bins that are too small for the next item if we are mid-stream
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 2. Global State Efficiency: Avoid opening new bins too early
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if other bins could fit the item
        score += (open_bins_count as f64 * 20.0) * (1.0 - progress);
        // If we are late in the stream, be more conservative about opening new bins
        score += progress * 50.0;
    }

    // 3. Fragmentation Control: Avoid creating "sliver" residuals that are unusable
    // A residual between 1 and 9 is often "dead space" because min item size is 10
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. Mean Residual Balancing: Prefer bins closer to the global average fill
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Urgency: If this is the only fitting bin, prioritize it to avoid forced new-bin creation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: punish large post_residuals (Best Fit logic)
    let mut score = post_res.powf(1.5);

    // Penalty for creating a "fragmented" bin: if post_residual is small but > 0, 
    // it's often worse than leaving it empty (or filling it perfectly).
    // We penalize small residuals that are unlikely to fit future items.
    if post_residual > 0 && post_residual < 20 {
        score += 50.0 * (1.0 - (post_res / 20.0));
    }

    // Lookahead coupling: If the next item fits into the current post_residual, 
    // we reward this placement significantly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 * (1.0 - (next_item_size as f64 / post_res));
    }

    // Dynamic pressure: As the stream progresses, favor tighter packing.
    // At the end of the stream, prioritize closing bins over opening new ones.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Penalty increases as we approach the end of the stream to avoid opening new bins.
        score += 35.0 + (progress * 45.0);

        // If we have many open bins that could fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 20.0;
        }
    } else {
        // Existing bin bonus: stabilize the distribution by keeping mean_residual balanced.
        // Penalize bins that are significantly emptier than the current mean.
        if (bin_residual as f64) > mean_residual {
            score += 5.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        }
