    }

    // Harmonic/Modulo logic: prioritize fitting items into bins that align with 
    // common item size multiples (e.g., 25, 33, 50).
    let alignment = (bin_capacity - post_residual) % 25;
    if alignment == 0 {
        score -= 5.0;
    }

    // Progression scaling: as the stream nears the end, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
