    // This helps keep bins packed somewhat uniformly.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 4. Tightness constraint:
    // Strongly prefer bins that are nearly full (Best Fit principle).
    score += (post_residual as f64) * 0.2;

    // 5. Progression scaling:
    // As the stream nears the end, be more aggressive about closing bins 
