        }
    } else {
        // 4. Fitting logic: If this is the last bin that can fit the item, prioritize it
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // 5. Best-Fit decreasing tendency: Reward tighter fits as we approach the end of the stream
        score += (post_residual as f64) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
