    }

    // Dynamic threshold: As the stream progresses, become more aggressive about 
    // filling bins tightly to avoid opening new ones.
    let tightness_bonus = (mean_residual - post) * progress;
    score -= tightness_bonus;

    // If this is the only bin that fits, prioritize it heavily to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Penalize this unless the current open bins are very poorly utilized.
    if bin_residual == bin_capacity {
        score += 40.0 - (progress * 10.0);
        // Only open a new bin if the average residual of existing bins is already quite high.
        score += mean_residual * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Favor small residuals (Best Fit) but avoid "sliver" waste.
    // If post_residual is very small (< 10), it often prevents future items from fitting.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 / (post_residual as f64);
    }

