    }

    // 4. Global Consolidation: Penalize opening new bins as the stream nears completion.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 35.0 + (progress * 20.0);
    }

    // 5. Harmonic Class Logic: Use modulo to identify "alignment" with bin capacity.
    // Items that leave a residual which is a multiple of 20 are generally more flexible.
    let alignment = (post_residual % 20) as f64;
    score += alignment * 0.5;

    // 6. Mean Residual Balancing: Discourage bins that deviate significantly from the mean
    // to keep open bins at similar occupancy levels.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small gaps that are likely to be wasted.
    // 0-9 is a "dead zone" for items arriving (min size 10).
    // If post_residual is in [1, 9], it is essentially unusable.

    let mut score = post_residual as f64;

