    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // If there are other bins that could fit the item, opening a new one is very expensive
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // Favor bins that align with the mean_residual of the system to maintain uniformity
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that result in smaller post_residual
    // We already start with post_residual as the base score.

    // 2. Lookahead Penalty/Bonus:
    // If next_item_size fits in the post_residual, drastically reduce score (prioritize this bin).
    if next_item_size > 0 && post_residual >= next_item_size {
