    }

    // 3. Penalty for creating "dead zones":
    // If post_residual is small but not zero, it might be unusable for future items (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. Mean Residual Balancing:
    // Avoid creating bins that are significantly tighter than the current average.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 15.0;
    }

    // 5. New Bin Thresholding:
    // If this is a new bin (residual == capacity), penalize it based on how many bins are already open.
    // This discourages opening new bins when existing ones could be utilized.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.0);
    }

    // 6. Last Chance Logic:
    // If this is the only bin that can fit the current item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 7. Progression scaling:
    // As we approach the end of the stream, prioritize filling existing bins more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Best-Fit Decreasing logic modulated by lookahead and bin density pressure.
    // Lower score is better.
    let mut score = post_residual as f64;

    // 1. If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless there are no existing bins that can fit the current item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0; // Strong penalty for opening a new bin prematurely
        } else {
            score -= 50.0;  // Reward opening a new bin if mandatory
        }
    }

    // 2. Lookahead logic: If the next item is large, favor bins that leave enough space
    // to accommodate it, or conversely, pack the current item into a bin that 
    // minimizes the "dead space" that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0; // Bonus: Current bin can fit the next item too
        } else if post_residual > 0 && post_residual < 10 {
            score += 30.0; // Penalty: Creating a sliver that likely can't fit anything
        }
    }

    // 3. Global state: Adjust preference based on the density of currently open bins.
    // If mean_residual is high, we have plenty of space, so be more selective (Best-Fit).
    // If mean_residual is low, we are tight, favor the most efficient packing.
    let density_factor = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
    score += density_factor * 10.0;

    // 4. Progress normalization: As we approach the end of the stream, 
    // prioritize clearing out smaller residuals to minimize bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    // 5. Fitting constraints: If this is the last chance for the item (fitting_bins_count == 1),
    // prioritize it significantly to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

