        // We use a Gaussian-like potential field centered at next_item_size.
        if next_item_size > 0 {
            let diff = (post_residual as f64 - next_item_size as f64).abs();
            score -= 25.0 * (-0.001 * diff * diff).exp();
        }

        // Penalty for creating a bin with a residual that is too small for most items (e.g., < 10)
        // unless it's a perfect fit (post_residual == 0).
        if post_residual > 0 && post_residual < 10 {
            score += 40.0;
        }

        // Encourage filling bins that are already partially full to keep open_bins_count low.
        // We penalize bins that are "too empty" relative to the current mean_residual.
        if bin_residual > (mean_residual as u32) {
            score += 15.0 * (bin_residual as f64 / bin_capacity as f64);
        }
    }

    // Heuristic: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
