    // 3. Global State: Discourage opening new bins early in the stream unless necessary
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one is available
            score += 60.0 * (1.0 - progress);
