    }

    // 4. Mean Residual Balancing: Avoid starving bins that are already well-filled
    // If this bin's residual is much smaller than the mean, prefer it to pack tighter
    if (post_residual as f64) < mean_residual {
        score -= 10.0 * (1.0 - progress);
    }

    // 5. Dynamic Horizon: As the stream ends, prioritize packing into existing bins
    if progress > 0.9 {
        if bin_residual == bin_capacity {
            score += 100.0;
        } else {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space after placement (Best Fit principle).
    // Lower post_residual is better, so we start with post_res.
    let mut score = post_res;

    // Penalty for creating a "sliver" (fragmentation): 
    // If post_residual is small but > 0, it is hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
