    // packing tightly over keeping many bins open.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Last chance to fit in an existing bin, heavily discount the score.
        score -= 20.0 * (1.0 + progress);
    }

    // If considering a new bin (bin_residual == bin_capacity), apply a penalty
    // that decreases as the stream progresses, allowing more new bins later.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is 40.0, scaled by stream progress.
        score += 40.0 * (1.0 - progress * 0.5);
    }

    // Non-linear coupling with mean_residual to penalize bins that deviate 
    // significantly from the average state of the system.
    let deviation = (post_res - mean_residual).abs();
    score += (deviation * progress).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
