pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Best-Fit Decreasing logic combined with a "Lookahead Harmonic Penalty".
    // 1. Base Score: The post_residual represents the space wasted if we stop here.
    // 2. Penalty for creating "dead zones": If post_residual is between 1 and 9, 
