pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // We want to pack tightly, but penalize creating "dead space" (residuals < 10) 
    // that are unlikely to accommodate future items.
    let mut score = post_res;

    // Penalty for creating a tiny residual that is hard to fill.
    // If post_residual is in the range [1, 9], it is effectively wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead coupling: If a second item is known, penalize bins that cannot fit it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding based on stream progression.
    // As we approach the end of the stream, prioritize closing bins (lower mean_residual).
    // If this bin is the last one that can fit the item, favor it slightly to avoid new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // Penalize opening a new bin (bin_residual == bin_capacity) relative to 
    // the average state of existing bins.
    if bin_residual == bin_capacity {
        score += 30.0 + (mean_residual * progress);
    }

    // Non-linear coupling: favor bins that result in a post_residual close to the 
    // current mean_residual to keep bin distribution uniform.
    let dev = (post_res - mean_residual).abs();
    score += 0.5 * dev * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We want post_residual to be as close to 0 as possible.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Reward placements that leave "useful" remainders
    // If post_residual is a multiple of 10, it is more likely to fit future items (10..80).
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    // 3. Lookahead Synergy: If next_item_size fits in post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Scarcity/Density Balancing:
    // If fitting_bins_count is low, we are running out of options; prioritize filling existing bins.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // 5. New Bin Thresholding:
    // Make opening a new bin expensive unless the current fit is extremely poor (large post_residual).
    if bin_residual == bin_capacity {
        // High base cost to open a new bin, adjusted by progress
        let progress = step_index as f64 / total_items as f64;
        score = 65.0 + (progress * 15.0);
    }

    // 6. Mean Residual Calibration:
    // If the current bin is significantly emptier than the average, penalize it to force consolidation.
    if (bin_residual as f64) > mean_residual * 1.2 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit common items
    // If post_residual is in the range (0, 10), it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Integration: If next item fits in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is very tight (Best Fit)
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless the item is large
    if bin_residual == bin_capacity {
        score += 15.0 + (item_size as f64 * 0.2);
    }

    // 4. Fitting Density: If this is the only bin that fits the item, make it highly attractive
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global Efficiency: Penalize high open bin counts to encourage bin consolidation
    score += (open_bins_count as f64) * 2.0;

    // 6. Mean Residual Balancing: If this bin's post-residual is significantly lower than 
    // the global mean, it is a good candidate for "filling up" the bin.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // However, we apply a non-linear scaling to allow for "near-perfect" fits.
    score += (post_residual as f64).powf(1.1);

    // 2. Lookahead Coupling: If a next item exists, reward bins where the current 
    // post_residual can accommodate the next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for "perfect" pairing (leaving 0 space)
            score -= (bin_capacity - (post_residual - next_item_size)) as f64 * 0.5;
        } else {
            // Penalty for stranding the next item (making it harder to fit)
            score += 15.0;
        }
    }

    // 3. Fragmentation Avoidance: If the post_residual is too small to fit any 
    // likely future items (e.g., < 10), it becomes "dead space".
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // 4. Strategic Opening: If this is an empty bin (new bin candidate), only 
    // choose it if the open bins are mostly "bad" (high mean_residual).
    if bin_residual == bin_capacity {
        // High cost to open a new bin unless the current mean_residual is very high
        score += 45.0 + (mean_residual * 0.5);
    } else {
        // Encourage using existing bins that are close to the mean residual
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score -= deviation * 0.2;
    }

    // 5. Urgency: As we near the end of the stream, prioritize closing bins
    // by preferring tighter fits.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best Fit principle).
    // Lower residual is generally better (tighter packing).
    let mut score = post_residual as f64;

    if is_new_bin {
        // Penalty for opening a new bin is dynamic:
        // As the stream progresses, it becomes more expensive to open new bins.
        // If there are many bins open, penalize opening more.
        score += 15.0 + (progress * 25.0) + (open_bins_count as f64 * 0.5);

        // If the item fits into an existing bin, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Lookahead heuristic: If the next item exists, favor placements that 
        // leave enough room for it.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                // Penalty for creating a gap that is too small for the next item
                score += 10.0;
            } else {
                // Reward for creating a "perfect" fit for the next item
                let slack = post_residual - next_item_size;
                if slack < 5 {
                    score -= 5.0;
                }
            }
        }

        // Global state awareness:
        // If the current bin's residual is significantly better than the mean, 
        // we want to preserve that bin for larger future items.
        if (bin_residual as f64) > mean_residual {
            score += 2.0;
        }

        // If this is the last chance for this item (fitting_bins_count == 1), 
        // accept it with high priority unless post_residual is extremely wasteful.
        if fitting_bins_count == 1 && post_residual > 20 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space: we prefer smaller post-residual (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": if the post-residual is too small to fit the 
    // average item size, it's effectively wasted. We use mean_residual as a proxy for 
    // bin state density.
    if post_res > 0.0 && post_res < mean_residual {
        score += 15.0 * (1.0 - (post_res / mean_residual));
    }

    // Lookahead logic: if the next item is large, penalize small residuals that 
    // would force a new bin later.
    if next_item_size > 0 {
        let lookahead_penalty = (next_item_size as f64 - post_res).max(0.0);
        score += lookahead_penalty * (1.0 - progress);
    }

    // Strategy shift: Early in the stream, favor tight packing. 
    // Late in the stream, be more aggressive to consolidate bins to avoid opening new ones.
    if fitting_bins_count == 1 && post_res > 5.0 {
        score += 20.0 * (1.0 - progress);
    }

    // Normalize empty bin selection: If this is an empty bin, its score is the capacity.
    // We apply a non-linear cost to opening new bins that increases as the stream progresses.
    if bin_residual == bin_capacity {
        score = 25.0 + (30.0 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score: The post_residual is the primary cost (Best Fit logic).
    let mut score = post_residual as f64;

    // Harmonic Penalty: Penalize residuals that are small but not zero (fragmentation).
    // Specifically, if post_residual < 10, it's often wasted space unless it's 0.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead Logic: If the next item can fit in the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless no other bin fits well.
    if bin_residual == bin_capacity {
        score += 25.0; 
        // If we are at the end of the stream, reduce the penalty of opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 10.0;
    }

    // Fitting Bins Logic: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Harmonic Class Modulation: Adjust score based on how well the item fills the bin capacity.
    // We prefer post_residuals that are multiples of 5 or 10 to leave "cleaner" space.
    if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Mean Residual Balancing: If the current bin's residual is significantly lower than the mean,
    // we are packing this bin tighter than average, which is usually good.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Strict Best-Fit with aggressive dead-space avoidance and bin-count regularization.

    // 1. Base Score: We prefer bins that leave the smallest residual (Best-Fit).
    let mut score = post_residual as f64;

    // 2. Dead Space Penalty: If the post_residual is small but not zero, it is likely unusable.
    // Penalize gaps in the [1, 9] range heavily, as they are too small for even the smallest items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 3. Lookahead Integration: If the next item cannot fit into this residual, 
    // we penalize the current placement to encourage saving space for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 4. Open Bins Pressure: If we are using many bins, penalize opening a new one.
    // If the bin is new, add a penalty proportional to the current open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 1.5;
    }

    // 5. Global Efficiency: If the current bin's residual is significantly worse than the 
    // mean residual of existing bins, penalize it to keep bin utilization uniform.
    if (bin_residual as f64) > mean_residual + 10.0 {
        score += 10.0;
    }

    // 6. Last-Chance Logic: If this is the only bin that fits, reduce the penalty 
    // to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that result in the smallest post_residual
    // This is the baseline, already captured by `score = post_residual`.

    // 2. Penalty for opening a new bin if we have options
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // High penalty for opening a new bin unless no other bin fits
        score += 50.0;
    }

    // 3. Lookahead Matching: 
    // If next_item_size fits in the post_residual, drastically reduce score to favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0; 
        // Bonus for "perfect" or "near-perfect" second-step fit
        let fit_diff = (post_residual - next_item_size) as f64;
        score -= (10.0 / (1.0 + fit_diff));
    }

    // 4. Mean Residual Balancing:
    // Avoid creating bins that are significantly "emptier" than the average open bin,
    // which prevents fragmenting space across too many bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Criticality check:
    // If this is the only bin that fits the current item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Progressive tightening:
    // As the stream progresses, favor tighter packing more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a 'sliver' (unusable space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if next item exists, favor bins that can accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual < next_item_size && post_residual >= 10 {
            score += 20.0;
        }
    }

    // Global state: if we have many open bins, penalize opening new ones
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 + progress) * (open_bins_count as f64).sqrt();
    }

    // Reward bins that bring the residual closer to the global mean (balancing load)
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // Last chance logic: if this is the only bin that fits the current item, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Dynamic horizon: as we approach the end of the stream, prioritize tight packing
    if progress > 0.8 {
        score += post_residual as f64 * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post_residual (Best Fit principle).
    let mut score = post_res;

    // Penalty for creating a "fragmented" bin: small residuals that are unlikely to fit future items.
    // We define "unusable" as less than the minimum item size (10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress.powf(0.5));
    }

    // Lookahead logic: If the next item is large, prioritize bins that leave enough space for it.
    // If the next item is small, prioritize bins that are nearly full.
    if next_item_size > 0 {
        let fit_margin = post_res - next_item_size as f64;
        if fit_margin < 0.0 {
            // Penalize bins that will definitely not fit the next item if we have other options.
            score += 15.0 * (1.0 - progress);
        } else {
            // Reward bins that leave a small, efficient buffer for the next item.
            score -= 10.0 * (1.0 / (1.0 + fit_margin));
        }
    }

    // New-bin inhibition: Only open a new bin if the fit is truly terrible or we are near the end.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin, which decreases as the stream ends.
        score += 45.0 * (1.0 - progress).powf(2.0);

        // If many bins are already open and could fit this, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0 * (fitting_bins_count as f64).sqrt();
        }
    }

    // Global density balancing: penalize bins that deviate significantly from the mean residual.
    let deviation = (post_res - mean_residual).abs();
    score += 0.5 * deviation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We want to minimize post_residual, but prioritize tight fits (near 0)
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic:
    // If the post_residual is small, it might be unusable for future items (10-80).
    // If post_residual is in (0, 10), it's "dead space". Heavily penalize this.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0 / (post_residual as f64);
    }

    // 3. Lookahead synergy:
    // If next_item_size fits in the current post_residual, reward this bin choice.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 200.0;
        // Further reward if it creates a "perfect" fit for the lookahead
        if post_residual == next_item_size {
            score -= 150.0;
        }
    }

    // 4. Distribution management:
    // If this is the only fitting bin, we are forced to use it unless the new bin 
    // heuristic is better. If we have many fitting bins, be more selective.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64) * 5.0;
    }

    // 5. New bin handling (bin_residual == bin_capacity):
    // Only open a new bin if the current state is very poor for existing bins.
    if bin_residual == bin_capacity {
        // High base cost to open a new bin to prevent fragmentation.
        score += 85.0;

        // If we are near the end of the stream, penalize opening new bins heavily.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 100.0;
    }

    // 6. Mean residual balancing:
    // If this bin's residual is significantly better than the mean, favor it.
    if (post_residual as f64) < mean_residual {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1-9), it is often "dead space"
    // because minimum item size is 10. We penalize these gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Open Bin Pressure: Discourage opening new bins if we have many bins already open.
    // This pushes the heuristic to consolidate items into existing bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
    }

    // 3. Lookahead Optimization: If the next item is large, prioritize bins that leave
    // enough room for it. If the current item fits but leaves next_item_size impossible,
    // we penalize that bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 4. Fitting Density: If this is the only bin that can fit the item, we make it
    // slightly more attractive to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // 5. Mean Residual Balancing: Favor bins that stay near the mean residual to
    // maintain a uniform distribution of fill-levels across open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best-Fit principle)
    // We prioritize bins that leave the least space.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If post_residual is close to next_item_size, reward it.
    // We want to avoid creating "orphaned" space by matching future needs.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 1.5;
    }

    // 3. Fragmentation Avoidance: If post_residual is very small (e.g., < 10), 
    // it's likely "dead space". Penalize these tiny gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Mean Residual Balancing: Favor bins that stay near the global average
    // to keep the bin distribution uniform.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // 5. New Bin Thresholding:
    // If we are looking at an empty bin (bin_residual == bin_capacity), 
    // penalize it unless no other bin can fit the item or all fits are poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have fits available.
            score += 150.0;
        } else {
