    // If this is a new bin (bin_residual == bin_capacity), only pick it if
    // the current packing is very inefficient (high mean_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0; // Forced: no other choice
        } else {
            // Penalize opening new bins unless the current average packing is poor.
            score += 40.0 + (mean_residual * 0.5) + (progress * 20.0);
        }
    } else {
        // 4. Fragment Avoidance:
        // If post_residual is small but not zero, it's often a "dead" space.
        // Penalize residuals that are too small to fit common items (e.g., < 10).
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // Reward bins that have a residual close to the current mean, 
        // encouraging uniform bin exhaustion.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 5. Final adjustment based on progress: 
    // Near the end of the stream, be more aggressive about packing into existing bins.
    if progress > 0.9 {
        score -= (open_bins_count as f64) * 0.5;
    }

