    // Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        // Only open a new bin if the progress is late and we have many open bins already,
        // or if fitting_bins_count is zero (enforced by logic).
        // Penalize new bin opening proportional to remaining capacity utilization.
        score += 45.0 + (progress * 20.0);
    } else {
        // Reward placements that leave a residual size compatible with the average expected item size
        // If post_residual is very small, it's a "tight fit" (good).
        // If post_residual is near the mean_residual, it's a "balanced fit" (good).
        let dist_to_mean = (post - mean_residual).abs();
