    if is_new_bin {
        if fitting_bins_count == 0 {
            score = 10.0; // Force open if no other choice
        } else {
            // Apply a heavy premium to opening a new bin prematurely.
            score = 40.0 + (mean_residual * 0.5);
        }
    } else {
        // Favor bins that maintain a healthy average residual to keep options open.
        score -= (bin_residual as f64 - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
