    // 5. Mean-Residual Balancing: Avoid bins that deviate significantly from the average 
    // fullness to keep variance low and ensure uniform bin usage.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 6. Last-Chance Logic: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
