    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. New bin penalty: If this bin is empty (new bin candidate), add a heavy penalty
    // to discourage opening new bins unless absolutely necessary (i.e., poor fits elsewhere).
    if bin_residual == bin_capacity {
        score += 45.0;

        // Dynamic adjustment: As we reach the end of the stream, be more conservative with opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 6. Mean-residual balancing: Discourage bins that deviate significantly from the current mean.
    // This helps keep the bin pack "balanced" in terms of remaining capacity.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

