    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 45.0;
    }

    // 3. Penalty for fragmentation: If post_residual is small but > 0, it's often 
    // "dead space". Penalize small remainders that cannot fit likely item sizes.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // 4. Global state awareness: If we are near the end of the stream, prioritize 
    // packing into existing bins to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        if bin_residual == bin_capacity {
            score += 60.0; // Strong penalty for opening new bins late-game
        }
    }

    // 5. Handling the "New Bin" candidate (bin_residual == bin_capacity):
    // Only open a new bin if the current fitting bins are all very poor fits.
    if bin_residual == bin_capacity {
        // If there are other bins that can fit this, make opening a new one expensive.
        if fitting_bins_count > 0 {
            score += 35.0;
        }
    }

    // 6. Dynamic balance: If the mean residual of existing bins is high, 
    // we should prioritize using those bins rather than creating new ones.
    if mean_residual > 30.0 && bin_residual != bin_capacity {
