    // We penalize high post_residual to favor tight packing.
    let mut score = post;

    // Interaction 1: Penalize opening a new bin (bin_residual == bin_capacity)
    // We apply a non-linear penalty that increases as the stream progresses,
    // discouraging new bin creation when many items have already been processed.
    if bin_residual == bin_capacity {
