    }

    // Interaction 2: Lookahead coupling
    // If the next item is large, we strongly penalize bins that would leave
    // a post_residual that is too small for the next item (dead space).
    if next_item_size > 0 {
        let next_item = next_item_size as f64;
        if post > 0.0 && post < next_item {
