    // Interaction 3: Density balancing
    // Penalize bins that deviate from the current mean_residual. 
    // This encourages keeping the remaining space in open bins somewhat uniform.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.25;

    // Interaction 4: Last chance pressure
    // If fitting_bins_count is 1, this bin is the only current option. 
    // We slightly reduce the score to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
