        if (post_residual - next_item_size) < 5 {
            score -= 20.0;
        }
    }

    // Heuristic for new bin allocation: 
    // If we are forced to open a new bin (fitting_bins_count == 0), 
    // ensure we don't penalize it excessively compared to bad fits in existing bins.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Only open a new bin if the existing bins are highly fragmented (mean_residual is small)
            if mean_residual > 25.0 {
                score += 40.0; // Discourage opening new bins early
            } else {
                score -= 10.0; // Encourage opening if current bins are mostly full
            }
        }
    } else {
        // Prefer bins that bring the residual closer to the global mean residual
        // to keep bin utilization balanced.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Progress-based scaling: As the stream nears the end, be more aggressive with packing
    // to avoid leaving items stranded.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual represents the "leftover" space. We want to minimize this, 
    // but we must avoid creating small, unusable gaps (1-9) if possible.

    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space": gaps between 1 and 9 are notoriously hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead bias: If the next item fits into the current post_residual, 
    // reward this bin highly to encourage "perfect packing" of pairs.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
