    // 3. Dynamic Horizon: As we near the end of the stream, prioritize closing bins
    // by being more aggressive with fitting items into existing gaps.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // 4. Global State: If the bin is new (bin_residual == bin_capacity), 
    // apply a penalty proportional to the current open_bins_count to discourage 
    // fragmenting space unnecessarily early in the stream.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // 5. Mean residual balancing: If this bin's post_residual is significantly 
    // lower than the global mean_residual, it is a "tight" fit. Reward it.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 6. Scarcity handling: If this is the only bin that can fit the current item, 
    // force it to be the choice by lowering its score significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize smaller post-residual (Best Fit principle)
    let mut score = post;

    // Penalty for creating "dead zones" (small residuals that are hard to fill)
    // We penalize residuals in the [1, 9] range heavily as they are unlikely to fit future items.
    if post > 0.0 && post < 10.0 {
        score += 50.0 / (post + 1.0);
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Stream progression coupling: 
    // Near the end of the stream, prioritize aggressive packing (lower residuals).
    // Early in the stream, allow for slightly more "slack" to keep bins open for future fits.
    score += (1.0 - progress) * (bin_capacity as f64 - post) * 0.2;

    // Adaptive threshold: If we only have one bin that fits, we are often forced to take it.
    // If fitting_bins_count is 0, this is a new bin candidate. 
    // We make new bins expensive early on, but cheaper as the stream progresses or if we have many open bins.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.0) - (progress * 20.0);
    }

    // Interaction with mean_residual: avoid deviating too far from the average state of our bins.
    score += (post - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
