pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1..9), it is often "unusable" 
    // for future items (since min item size is typically 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bin Pressure: Penalize opening new bins unless the fit is excellent.
    // If we are looking at a new bin (bin_residual == bin_capacity), add a significant penalty.
    if bin_residual == bin_capacity {
        score += 35.0; 
    }

    // 3. Lookahead Synergy: If the next item can fit in the post_residual space, 
    // reward this placement significantly to prioritize packing pairs.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 4. Fitting Bin Scarcity: If this is the ONLY bin that can fit the item, 
    // we should prioritize it to avoid the cost of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. Global Efficiency: If the current bin's residual is much higher than the mean,
    // we prefer to fill this bin rather than creating a new one or filling a tighter bin.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 6. Progression Scaling: As we approach the end of the stream, 
    // minimize the penalty for opening new bins to ensure we don't leave items stranded.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.95 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin (if fitting_bins_count > 0)
    // We heavily penalize opening a new bin unless the current fit is terrible.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0;
    }

    // 2. Best-Fit logic: punish large post_residuals (slack)
    // We want to minimize the space left over.
    score += post_residual as f64 * 0.5;

    // 3. Lookahead synergy:
    // If we have a next item, we want the current post_residual to fit it perfectly.
    // We reward post_residuals that are slightly larger than the next_item_size,
    // and heavily penalize those that are smaller (forcing a new bin for the next item).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward perfect or near-perfect fit for the next item
            score -= (100.0 - (post_residual - next_item_size) as f64) * 0.3;
        } else {
            // Penalty for stranding the next item
            score += 30.0;
        }
    }

    // 4. Global balance:
    // Avoid creating bins that deviate significantly from the current mean_residual.
    // This helps maintain a consistent "tightness" across all open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Urgency:
    // If this is the only bin that fits the item (fitting_bins_count == 1),
    // we should prioritize using it to avoid opening a new one later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Progression factor:
    // As we approach the end of the stream, prioritize closing bins (lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // If the bin is new, calculate a penalty based on the difficulty of packing current/next items
    // If the bin is existing, prioritize tighter fits (Best-Fit) but account for future item compatibility.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base score: Favor smaller post_residual (Best-Fit logic)
    let mut score = post_residual as f64;

    // 2. Penalize new bins heavily unless we are forced to open one
    if is_new_bin {
        // High penalty to prevent opening new bins unnecessarily
        score += 45.0;

        // If we have many open bins with high residuals, discourage opening a new one
        if mean_residual > 20.0 {
            score += mean_residual * 0.5;
        }
    } else {
        // 3. Lookahead: Penalize if the current choice prevents the next_item_size from fitting
        if next_item_size > 0 && post_residual < next_item_size {
            // If this bin becomes unusable for the next item, apply a penalty
            score += 15.0;

            // If this was our only fitting bin, the penalty for making it unusable is higher
            if fitting_bins_count == 1 {
                score += 25.0;
            }
        }

        // 4. Global balance: If we are near the end of the stream, prioritize aggressive packing
        if progress > 0.9 {
            score -= (100.0 - post_residual as f64) * 0.1;
        }
    }

    // 5. Dynamic constraint: If fitting_bins_count is low, we are constrained; reward utilizing existing bins
    if !is_new_bin && fitting_bins_count > 0 {
        score -= (fitting_bins_count as f64).ln() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // The core objective is to minimize post_residual (Best Fit), but we introduce
    // non-linear penalties for creating "unusable" gaps, especially as the stream progresses.
    // A gap size < 10 is often unusable, so we penalize small post_residuals.
    let gap_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post).powf(1.5) * 5.0
    } else {
        0.0
    };

    // Reward bins that align well with the next item (Lookahead anticipation)
    let lookahead_reward = if next_item_size > 0 {
        let fit_next = post >= next_item_size as f64;
        if fit_next { -15.0 * (1.0 - progress) } else { 10.0 * progress }
    } else {
        0.0
    };

    // Penalize opening new bins heavily early on, but allow it more freely near the end
    // to consolidate remaining items.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (open_bins_count as f64 * 2.0) * (1.0 - progress).powi(2) + 20.0
    } else {
        0.0
    };

    // Prioritize bins that are closer to the mean_residual to keep bin distribution uniform
    let variance_penalty = (post - mean_residual).abs() * 0.5;

    // fitting_bins_count == 1 acts as a "last chance" signal; prioritize filling it.
    let scarcity_bonus = if fitting_bins_count == 1 && !is_new_bin { -25.0 } else { 0.0 };

    post + gap_penalty + lookahead_reward + new_bin_penalty + variance_penalty + scarcity_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit logic: Minimize post_residual (already in base score)
    // 2. Penalty for creating "dead space": small residuals that cannot fit common items.
    // If post_residual is in (0, 10), it is very likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 3. Lookahead optimization: If next_item_size is known, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // High reward for leaving space for the next item
            score -= 25.0;
        } else {
            // Penalty for stranding the next item if we have other options
            score += 15.0;
        }
    }

    // 4. Thresholding: If this is the only bin that fits, we are forced to take it.
    // We lower the score to ensure this bin is preferred over opening a new one.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // 5. Global efficiency: If we are near the end of the stream, prioritize bin consolidation.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // More aggressive packing at the end to close bins
        score += (post_residual as f64) * 0.5;
    }

    // 6. New bin bias: If bin_residual == bin_capacity, we are evaluating a brand new bin.
    // Only open a new bin if the score is significantly lower than existing ones.
    if bin_residual == bin_capacity {
        // High base cost to open a new bin
        score = 85.0;

        // If we have many open bins, we should avoid opening new ones unless absolutely necessary.
        score += (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, while penalizing small unusable gaps (1..10)
