    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Logic: If the next item fits perfectly into this post_residual, 
    // highly reward this bin (Aggressive matching).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Smaller penalty if it still fits, but not perfectly.
            score -= 10.0;
        } else {
            // If the next item cannot fit, we penalize based on how much it misses by.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // 4. Mean Residual balancing:
    // Avoid creating bins that deviate significantly from the current average residual.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // 5. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), make it expensive
    // unless fitting_bins_count is low or the item is very large.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0; // Necessary evil
        } else {
            score += 60.0; // Strongly discourage opening new bins if we have space
        }
    }

    // 6. Progress factor:
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (progress * 30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize "sliver" waste (1-9 space)
    // because small slivers are rarely filled by future items.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 - (post_residual as f64 * 2.0);
    }

    // 2. Lookahead Synergy: If next_item_size is known, favor bins that can fit it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Strong reward for accommodating potential next item
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 10.0; // Penalize creating a bin that cannot fit the next item
        }
    }

    // 3. Global State Balancing: Avoid flooding with many open bins late in the stream.
    // If we are near the end of the stream, prioritize closing bins (lower post_residual).
    if progress > 0.8 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 4. New Bin Logic: If bin_residual == bin_capacity, we are evaluating a "New Bin".
    // We only open a new bin if the current "best" fit is exceptionally poor (e.g., post_residual < 10).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other bins exist, unless those bins are very tight.
            score += 40.0 + (mean_residual * 0.5);
        } else {
            // Must open a new bin if no other fits.
            score = 0.0;
        }
    }

    // 5. Dynamic Density: Favor bins that maintain the mean residual to keep packing uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize tightest fit (Best Fit)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: proportional to progress to discourage early fragmentation
    // but allow it if the current open bin options are poor.
    if is_new_bin {
        // New bins are expensive early on, but potentially necessary as the stream ends.
        score += 25.0 * (1.0 - progress);
    } else {
        // If this bin is the only one that fits, reward it significantly to avoid new bin creation
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // Lookahead penalty: if the next item is large, avoid leaving small residuals
        // that are unlikely to accommodate the next item.
        if next_item_size > 0 {
            let space_loss = (post_residual as f64 - next_item_size as f64).abs();
            score += 0.5 * space_loss * (1.0 + progress);
        }
    }

    // Dynamic balancing: if the mean residual is high, we are being too loose with bin usage.
    // Tighten the scoring to penalize large post_residuals more heavily.
    score += (mean_residual / bin_capacity as f64) * post_residual as f64;

    // Non-linear coupling: penalize very small, unusable residuals that are unlikely to fit future items.
    // A residual < 10 is often "dead space" unless the item stream contains tiny items.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

