    // 3. Last-Chance Constraint: If this is the only bin that can fit the item,
    // strongly prefer it to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 4. Global Density Normalization:
    // As the stream progresses, become more aggressive about filling existing bins
    // to prevent a tail-end spike in bin usage.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 15.0;

    // 5. Residual Balancing:
    // Penalize bins that deviate significantly from the mean residual.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
