    let dev = (post - mean_residual).abs();
    score += 0.2 * dev * (1.0 + progress);

    // Criticality logic:
    // If fitting_bins_count is 1, this is the only bin that can take the current item.
    // We should reward this heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Non-linear penalty for "dead space" fragmentation:
    // Highly small residuals (e.g., < 5) are often unusable.
    if post < 5.0 && post > 0.0 {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large remaining space (post_residual).
    // We prioritize bins that result in small post_residual (Best Fit).
    // If bin is new (bin_residual == bin_capacity), apply a heavy penalty to favor packing into open bins.
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 2. Harmonic Class Logic: Reward post_residuals that are multiples of common item sizes (20, 25, 33).
    // This reduces fragmentation by leaving "useful" gaps for future items.
    let remainder = post_residual % 20;
    if remainder == 0 {
        score -= 12.0;
    } else if post_residual < 10 {
        // Very tight fit is excellent, reward it.
        score -= 25.0;
    }

    // 3. Lookahead Logic: If the next item fits into the current post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 35.0;
    }

    // 4. Fragmentation Control: Penalize bins that deviate significantly from the mean_residual.
    // Keeping residuals uniform helps fit items later in the stream.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 5. Urgency Adjustment: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progressive Scaling: As the stream nears the end, become more aggressive about fitting.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "unusable" small gaps (dead space < 10, as items are >= 10).
    // If post_residual is in [1, 9], it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. If this is a new bin (bin_residual == bin_capacity), penalize it based on 
    // how many other bins are already available. We want to avoid opening new bins
    // unless the fit in existing bins is truly terrible.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.0);
    }

    // 3. Lookahead heuristic: If the next item exists, penalize placements that
    // make it impossible to fit the next item if we have very limited space.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize cutting off the ability to pack the next item in this bin
            score += 15.0;
        }
    }

    // 4. Pressure: If we have many open bins, prioritize filling the ones that 
    // are already "tight" to maximize density.
    if fitting_bins_count > 0 {
        let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= tightness * 10.0;
    }

    // 5. Progression: As we approach the end of the stream, prioritize 
    // closing open bins (lower residual) over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
