    // 4. Global Density Control:
    // If the bin's post_residual is significantly higher than the mean_residual, 
    // it suggests we are under-utilizing this bin compared to others.
    if (post_residual as f64) > mean_residual {
        score += 15.0;
    }

    // 5. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), only pick it if the score
