    // 4. Global state management:
    //    If we are near the end of the stream, prioritize closing bins (minimizing open_bins_count).
    if progress > 0.8 {
        score += (open_bins_count as f64) * 5.0;
    }

    // 5. New bin thresholding:
    //    Only open a new bin if the current fit is "bad" (e.g., leaving a large, inefficient residual)
    //    or if we have very few fitting options.
    if bin_residual == bin_capacity {
        // High base cost to open a new bin, dynamic based on how many bins are already open
        score = 45.0 + (open_bins_count as f64 * 2.0);

        // If we have plenty of open bins that could fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 60.0 * (1.0 - progress);
        }
    }

    // 6. Balance against mean_residual to avoid fragmented bins
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space after placement. 
    // We want to minimize this (Best Fit principle).
    let mut score = post_res;

    // Penalty for creating a bin that is too empty (high post_residual).
    // We scale this penalty by the progression of the stream to encourage 
    // tighter packing as we approach the end of the stream.
    let emptiness_penalty = post_res * (1.0 + progress);
    score += emptiness_penalty;

    // If this is the only bin that fits the current item, prioritize it 
    // heavily to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Lookahead mechanism: if next_item_size is large, avoid leaving a residual 
    // that is just slightly too small to fit the next item.
    if next_item_size > 0 {
        let diff = post_res - next_item_size as f64;
        if diff < 0.0 {
            // Penalize bins that will be too small for the next item, 
            // but prioritize bins that leave exactly enough space.
            score += 50.0 * (1.0 + (diff.abs() / 100.0));
        } else {
            // Reward bins that have just enough room for the next item.
            score -= 20.0 * (1.0 / (1.0 + diff));
        }
    }

    // Discourage opening new bins (bin_residual == bin_capacity) 
    // unless the current open bins are very poorly utilized.
    if bin_residual == bin_capacity {
        // Only consider a new bin if the average residual of open bins 
        // is already very low (meaning we are running out of space).
        score += 80.0 + (mean_residual * 2.0);
    }

    // Bias against having too many open bins simultaneously.
    score += (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual while avoiding "unusable" small gaps (1-9).
    // The strategy uses harmonic-inspired weights to favor tight fits (Best-Fit) 
    // while penalizing the creation of gaps that are likely to remain empty.

    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead zones" (gaps < 10, as min item size is 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual, 
    // prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Harmonic weight: Favor bins that are already "half-full" or more to consolidate
    // space, using the mean_residual as a density anchor.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // 4. Thresholding: If this is the only bin that fits the item (fitting_bins_count == 1),
    // and it's a "bad" fit (post_residual is large), penalize it slightly to encourage
    // a new bin if the current one is too empty to be efficient.
    if fitting_bins_count == 1 && post_residual > 40 {
        score += 15.0;
    }

    // 5. New Bin logic: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only want to open a new bin if the existing options are extremely inefficient.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to prevent fragmentation.
        score = 45.0;

        // If we have many bins open but they are all very full, opening a new one is okay.
        if open_bins_count > 0 && mean_residual < 20.0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
