    // but large enough to waste space (e.g., 1-9 is often 'dead space').
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Best-Fit Bias: Encourage tighter packing by heavily rewarding small post_residuals.
    score += (post_residual as f64) * 0.5;

