        // Reward tighter fits that leave exactly enough space for the next item.
        let waste = post_residual - next_item_size;
        score += waste as f64 * 0.2;
    }

    // 3. Pressure management: If we are running out of items, be more aggressive about closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 20 {
        score -= 10.0;
    }

    // 4. Mean Residual balancing: Penalize bins that deviate too far from the average state.
    // This keeps the "density" of open bins uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 5. Urgency: If this is the only bin that can fit the item, prioritize it to avoid 
    // unnecessary new bins unless the fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
