pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Heuristic Strategy: Best-Fit Decreasing variant with a penalty for creating small, unusable residuals
    // (the "fragmentation trap") and a reward for leaving space that fits the lookahead item.

    let mut score = post_residual as f64;

    // 1. Penalty for creating small, unusable gaps (1..9).
    // These gaps are highly unlikely to be filled by future items (size 10+).
