pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space left: we prefer smaller post_residual (Best Fit).
    // Penalize empty bin opening unless necessary: 
    // If bin_residual == bin_capacity, it is a new bin.
    let is_new_bin = bin_residual == bin_capacity;

    // We want to avoid creating "dead space" (residuals < 10, as items are >= 10).
    // A residual between 1 and 9 is lethal; punish it quadratically.
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        (10.0 - post_res).powi(3)
    } else {
        0.0
    };

    // Use next_item_size to anticipate fit. If the next item fits into the current post_residual,
    // reward this bin to keep the packing tight.
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        -25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // If we are late in the stream, prioritize closing bins (lower mean_residual) 
    // over starting new ones.
    let progress_penalty = if is_new_bin {
        (200.0 * progress) + (open_bins_count as f64 * 5.0)
    } else {
        0.0
    };

    // If this is the only bin that fits, we are forced to pick it; 
    // keep the score low to ensure it is selected.
    let necessity_bonus = if fitting_bins_count == 1 && !is_new_bin {
        -50.0
    } else {
        0.0
    };

    let mut score = post_res + dead_space_penalty + lookahead_bonus + progress_penalty + necessity_bonus;

    // Penalize large residuals more aggressively as the stream progresses
    score += (post_res / bin_capacity as f64) * 10.0 * progress;

    score
}

