    }

    // Lookahead logic: If the next item cannot fit in the current post_residual,
    // we penalize this placement to favor bins that can accommodate the next item.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += 25.0 * (1.0 - progress);
    }

    // Dynamic thresholding: As we approach the end of the stream, 
    // we become increasingly desperate to close bins (minimize new bin opening).
    // Penalize the "New Bin" candidate (bin_residual == bin_capacity) heavily as progress increases.
    if bin_residual == bin_capacity {
        score += 40.0 + (progress * 60.0);
    }

    // Balance open bins: If we have many open bins, penalize opening yet another one
    // unless the fit is extremely tight (post_residual near 0).
    if fitting_bins_count == 0 {
        score -= (open_bins_count as f64 * 0.5);
    }

    // Encourage filling bins that are already "drained" (low mean_residual)
    // to keep the distribution of residuals uniform.
    score += (post - mean_residual).abs() * 0.2;

