    // prioritize closing bins (minimizing open_bins_count).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. 
    // We prioritize Best-Fit (small post_residual) but penalize fragmentation 
    // and reserve space for upcoming items (lookahead).

    let mut score = post_residual as f64;

    // 1. Penalize creating "unusable" small gaps (1-9 range) unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead: If next_item_size is large, avoid bins that leave little room for it.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // Penalize bins that cannot fit the next item if we have other bins available
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // 3. Global State: If we have many open bins, prioritize filling existing bins (Best-Fit).
    // If we have few open bins, we can be more selective to avoid fragmentation.
    if open_bins_count > 5 {
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Strategic New Bin Opening:
    // Only open a new bin if the current fit is poor (post_residual is large)
    // and we are not near the end of the stream.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: decreases as we get closer to the end of the stream
        // to ensure we don't have dangling items.
        score += 30.0 * (1.0 - progress);
    }

    // 5. Fitting constraint: If this is the only bin that fits, prioritize it heavily
    // to prevent unnecessary new bin openings.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Mean Residual Balancing:
    // Favor bins that are closer to the current mean residual to keep bin states uniform.
    let diff_from_mean = (bin_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

