        // plus a penalty based on how many bins are already open.
        score = (bin_capacity as f64 - item_size as f64) + (open_bins_count as f64 * 0.8);
    } else {
        // Apply a penalty for leaving a bin with very little space, 
        // as this prevents future larger items from fitting.
        if post > 0.0 && post < 10.0 {
            score += (10.0 - post) * 1.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
