    // 2. Open Bin Pressure: If we have many open bins, prioritize filling existing ones.
    // If we have very few, we are more selective to prevent opening new ones later.
    score += (open_bins_count as f64) * 2.5;

    // 3. Lookahead Sensitivity: If the next item is large, favor bins that leave enough room 
    // for it, or conversely, if the current bin can't fit the next item, penalize it slightly.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
