    }

    // 4. New Bin Thresholding: If this is a new bin (residual == capacity), add a high base cost
    // to force the algorithm to prefer fitting into existing bins unless the fit is truly awful.
    if bin_residual == bin_capacity {
        score += 60.0 + (open_bins_count as f64 * 2.0);
    }

    // 5. Fitting Constraint: If this is the last chance to place an item in an existing bin, 
    // provide a massive discount to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
