    // yet too large to be ignored, using harmonic-style thresholds.

    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space (residuals < 10 are rarely useful for items >= 10)
    // If post_residual is in the range [1, 9], it's likely dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead logic: If a bin can fit the NEXT item, reward it.
    // This effectively implements a variation of "Next-Fit-Decreasing" logic.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Penalty for opening a new bin prematurely.
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless no other bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 40.0;
        } else {
            score -= 10.0;
        }
    }

    // 4. Harmonic balancing: Penalize residuals that are near-multiples of typical item sizes
    // to keep bins aligned for potential future packing.
    let harmonic_penalty = (post_residual % 25) as f64 * 0.5;
    score += harmonic_penalty;

    // 5. Global density pressure: As the stream progresses, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone": post_residual values that are too small to fit typical future items
    // but large enough to waste space. We penalize gaps in the (0, 10) range heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // Penalty for opening a new bin when existing bins could accommodate the item.
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0 + (open_bins_count as f64 * 2.0);
    }

    // Reward bins that become "perfect fits" or near-perfect fits to reduce global fragmentation.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 5 {
        score -= 5.0;
    }

    // Lookahead logic: if the next item is large and current post_residual is small, 
    // it's better to use a different bin to avoid forced new-bin creation later.
    if next_item_size > post_residual && post_residual < 20 {
        score += 15.0;
    }

    // Pressure normalization: penalize creating too many bins as the stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 5.0;

    // Favor bins that align with the current mean residual to keep bin states uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that is too small for common future items.
    // If post_residual is small but > 0, it is often worse than 0 (perfect fit).
    if post_residual > 0 && post_residual < 15 {
        score += 50.0;
    }

    // 2. Aggressive 2-step lookahead: 
    // If we have a next item, favor bins where the post_residual can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that create a "tight" fit for the predicted next item.
            score -= (bin_capacity - (post_residual - next_item_size)) as f64 * 0.5;
        } else {
            // Penalize if this placement prevents the next item from fitting here.
            score += 20.0;
        }
    }

    // 3. Balance against global state:
    // If we have many bins open, be more conservative (avoid new bins).
    // If we have few bins open, prioritize tight packing (Best Fit).
    if bin_residual == bin_capacity {
        // This is a new bin. Penalize it heavily if we have existing bins that could fit the item.
        score += (open_bins_count as f64) * 15.0;
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // Reward bins that keep the mean residual low, preventing fragmentation.
        score += (post_residual as f64 - mean_residual) * 2.0;
    }

    // 4. Progress-based scaling:
    // As we approach the end of the stream, prioritize closing bins (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Best-Fit Decreasing logic augmented with lookahead-aware packing density.
    // We prioritize bins that leave the smallest residual, but penalize bins that 
    // leave "dead" space that cannot accommodate the next item or future average items.

    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin unnecessarily early
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
