    }

    // 2. Lookahead: Penalize if the post_residual is too small to fit the next item
    // but the next item is large enough that it would have fit otherwise.
    if next_item_size > 0 && post_residual < next_item_size {
        // If we create a "dead" gap that is too small for the next item, penalize it.
        // We scale this penalty by the size of the next item to prioritize keeping
