    // 3. Density Balancing: If we are late in the stream, favor tighter packing 
    // to close out bins, otherwise favor keeping bins slightly open for flexibility.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Late stage: Heavily penalize large residuals to force completion
        score += post_residual as f64 * 0.5;
    } else {
        // Early stage: Encourage keeping bins with higher residuals (more capacity)
        // to accommodate potential future large items.
        score -= (bin_residual as f64 - mean_residual) * 0.1;
    }

    // 4. Critical thresholding: If this is the last fitting bin, prioritize it 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // We prioritize Best-Fit (minimizing post_residual) but penalize small residuals 
    // that are likely to become stranded (the "fragmentation threshold").
    let mut score = post_residual as f64;

    // Penalize new bin creation heavily, scaling down as we approach the end of the stream
    // to allow for better packing density in the final stages.
    if is_new_bin {
        score += 25.0 * (1.0 - progress).powf(0.5) + (open_bins_count as f64 * 0.5);
    } else {
        // Reward bins that bring the residual closer to the mean_residual of existing bins,
        // which helps keep bin states homogeneous.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;

        // Lookahead heuristic: If the next item fits into the current post_residual, 
        // give this bin a strong preference.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }

        // If this is the only bin that can fit the item, prioritize it to avoid 
        // opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Non-linear penalty for creating "dead zones" (residuals between 1 and 9 are 
    // notoriously hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
