    // 3. Fragmentation Control: Penalize bins that create "odd" remainders 
    // relative to the mean residual of the system.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 4. New Bin Thresholding: If this is a new bin (bin_residual == bin_capacity),
