        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead optimization: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open bins pressure: If we are nearing the end of the stream, discourage opening new bins.
    // If this is a new bin (bin_residual == bin_capacity) and we have other options, penalize it.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one can accommodate the item.
            score += 100.0;
        }
        // Scale penalty by progress: harder to justify new bins late in the stream.
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // 4. Compactness bias: Favor bins that stay near the mean residual of the system to prevent fragmentation.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Efficiency incentive: Prefer bins that are nearly full (Best Fit archetype).
    // Specifically target a "tight" fit (residual 0-5) as the ideal state.
    if post_residual <= 5 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large remaining space to keep bins packed tightly.
    // We favor bins where post_residual is as small as possible.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If the next item fits perfectly in the remaining space,
    // we reward this placement heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward small gaps after the next item is placed
        score -= (100.0 - diff) * 0.8;
    }

    // 3. New Bin Thresholding: Prevent premature new bin opening.
    // If this is a new bin (residual == capacity), penalize it based on how many
    // existing bins could have taken the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other options exist.
            score += 250.0 + (fitting_bins_count as f64 * 50.0);
        } else {
            // If no other bin fits, this is a necessary evil.
            score -= 10.0;
        }
    }

    // 4. Global Packing Efficiency: If the current bin's post-residual is significantly 
    // lower than the mean residual of all open bins, it's a good candidate.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // 5. Progression Bias: As the stream nears the end, become more aggressive 
    // about closing bins (minimizing total bins used).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Strategy: Favor "Best Fit" (smallest post_residual) while reserving space for lookahead, 
    // and penalizing new bin creation unless necessary or highly efficient.

    let mut score = post_residual as f64;

    // 1. Penalize empty bin creation unless no other bin fits (Best Fit constraint)
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0; // Strong penalty for opening a new bin if we can fit elsewhere
        } else {
            score -= 50.0; // Reward opening if it's the only option
        }
    }

    // 2. Lookahead optimization (k=2)
    // If the next item is large, avoid creating a residual that is just slightly too small 
    // for the next item (dead space creation).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // This is a "bad" fit because it creates a trap for the next item
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else if post_residual >= next_item_size {
            // This is a "good" fit, it leaves room for the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 3. Global state balancing
    // If we have many open bins, prioritize tightening existing bins (Best Fit).
    // If we have few open bins, allow slightly more slack to keep future options open.
    let progress = step_index as f64 / total_items as f64;
    if open_bins_count > 5 {
        score += (post_residual as f64) * 0.8;
    }

    // 4. Tightness bias
    // Penalize very small slivers of space (1-5 units) as they are rarely useful.
    if post_residual > 0 && post_residual < 6 {
        score += 20.0;
    }

    // 5. Mean residual equilibrium
    // Penalize bins that deviate significantly from the mean residual of the system.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 6. Near-end-of-stream phase
    // As we reach the end, prioritize filling bins completely (aggressive Best Fit).
    if progress > 0.9 {
        score -= (bin_capacity - post_residual) as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating a 'fragment' bin: if the post_residual is small but 
    // greater than 0, it creates unusable space for most items (10-80).
    // We penalize values in the (0, 10) range heavily.
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead coupling: if the next item is large, favor bins that leave 
    // enough room for it. If post_residual < next_item_size, apply a penalty.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 40.0 * (1.0 - (post / next_item_size as f64));
        }
    }

    // Stream progression coupling: As the stream nears the end, become more 
    // aggressive about filling existing bins (minimizing open_bins_count).
    // We penalize opening new bins (bin_residual == bin_capacity) more as progress increases.
    if bin_residual == bin_capacity {
        score += 25.0 + (35.0 * progress);
    }

    // Interaction with mean_residual: If the current bin is "emptier" than the average,
    // it is a better candidate to absorb the item to balance bin fill rates.
    let residual_diff = bin_residual as f64 - mean_residual;
    score -= 10.0 * (residual_diff / bin_capacity as f64);

    // If this is the only bin that can fit the item, prioritize it to avoid 
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We want to minimize post_residual, so it stays as the base score.

    // 2. Harmonic Class logic:
    // If post_residual is small, it creates "dead space" that cannot fit future items.
    // If post_residual < 10, it's likely unusable (since min item size is usually > 10).
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // 3. Lookahead Logic:
    // If next_item_size fits in the post_residual, reward this bin placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
    }

    // 4. Fitting Bin Scarcity:
    // If this is the only bin that can fit the current item (fitting_bins_count == 1),
    // and we are considering opening a new bin (bin_residual == bin_capacity),
    // heavily penalize the new bin to force usage of the existing one.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 100.0;
    }

    // 5. Fragmentation Control:
    // Penalize placements that deviate significantly from the mean residual of existing bins,
    // as this keeps bin states clustered.
    let diff = (post_residual as f64 - mean_residual).abs();
    score += diff * 0.2;

    // 6. Progressive packing:
    // Toward the end of the stream, prioritize aggressive packing (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "dead" gaps 
    // that are too small to fit common items (10-20), while balancing bin count pressure.

    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is between 1 and 9, it is highly likely to be wasted.
    // We increase the score (penalize) for these gaps to force tighter fits.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item can fit in the current post_residual, 
    // we reward this placement to keep the bin useful for the immediate future.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the current options 
    // force a very poor fit (large post_residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only consider a new bin if the current open bins are all poor fits.
        // Penalty grows with the number of open bins to consolidate.
        score += (open_bins_count as f64) * 15.0;
    } else {
        // Reward utilizing existing bins to reduce open_bins_count.
        score -= (10.0 / (fitting_bins_count as f64 + 1.0));
    }

    // 4. Global Distribution Balancing: If the current bin's residual is much higher 
    // than the global mean, we penalize it to prioritize more "average" bins.
    if !is_new_bin {
        let residual_delta = (bin_residual as f64 - mean_residual).abs();
        score += residual_delta * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score is the remaining space; we want to minimize this (Best Fit)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0; // High barrier to opening a new bin if space exists
        } else {
            score = 0.0; // Neutralize for inevitable new bin
        }
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // reward this placement to keep the bin useful for the next step.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // Adaptive thresholding: penalize residuals that are too small to be useful 
    // for future items but too large to be considered "packed".
    // If post_residual is between 1 and 9, it's likely "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Global optimization: favor bins that align with the mean residual of the set
    // to keep the bin distribution uniform and prevent fragmentation.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.1;

    // Progression awareness: Towards the end of the stream, be more aggressive
    // about filling existing bins to avoid leftover bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the residual space after placement (Best Fit strategy)
    let mut score = post_residual as f64;

    // Penalty for creating a bin that is too empty early on, or too tight later on.
    // If we are near the end of the stream, we want to maximize utilization (minimize residual).
    // If we are at the beginning, we favor bins that leave room for future items.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: proportional to progress and open bins
        score += 25.0 + (open_bins_count as f64 * 0.5) + (progress * 15.0);
    } else {
        // Reward placements that leave a residual close to the mean residual (load balancing)
        let balance_diff = (post_residual as f64 - mean_residual).abs();
        score += balance_diff * 0.2;

        // Lookahead heuristic: if the next item can fit in the post_residual, reduce penalty
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }

        // If this is the only bin that can fit the item, prioritize it to avoid wasting space
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Penalty for creating 'dead space' (residual too small to fit anything useful, e.g., < 10)
        if post_residual < 10 && post_residual > 0 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit)
    let mut score = post_res;

    // Penalty for creating "dead space" (small residuals that are unlikely to fit future items)
    // We define "dead" as < 20. We penalize this more heavily as the stream progresses.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * (1.0 + 2.0 * progress);
    }

    // Lookahead logic: If the next item is large, avoid bins that leave very little room
    // or conversely, if the next item is small, favor bins that leave room for it.
    if next_item_size > 0 {
        let fit_next = (post_residual as i32 - next_item_size as i32) as f64;
        if fit_next < 0.0 {
            // Penalty for stranding the next item
            score += 15.0 * (1.0 - progress);
        } else {
            // Reward bins that can accommodate the next item perfectly
            score -= (10.0 - fit_next.abs()).max(0.0) * 0.5;
        }
    }

    // New Bin Logic:
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    // Discourage new bins unless necessary (fitting_bins_count is low or residuals are poor).
    if bin_residual == bin_capacity {
        // As the stream nears the end, opening new bins becomes increasingly expensive.
        score += 30.0 + (40.0 * progress);

        // If we have many fitting bins, a new bin is almost always a bad choice.
        score += (fitting_bins_count as f64) * 10.0;
    } else {
        // For existing bins, reward utilizing bins that are already "fuller" (lower mean_residual)
        // to keep the open bin count low.
        score -= (100.0 - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit).
    // We prioritize bins that result in the smallest remaining gap.
    score += post_residual as f64 * 0.1;

    // 2. Harmonic Class Logic: 
    // If post_residual is small (e.g., < 10), it's a "tight fit", which is highly desirable.
    if post_residual < 10 {
        score -= 25.0;
    }

    // 3. Lookahead Synergy:
    // If the next item can fit into the current post_residual, reward this bin placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if the resulting gap after the next item is also very small (harmonic pairing).
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next < 5 {
            score -= 15.0;
        }
    }

    // 4. New Bin Thresholding:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Only open a new bin if the current open bins are "bad" (i.e., their mean residual is high).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual < 20.0 {
            // Penalize opening a new bin if existing bins have plenty of space.
            score += 100.0;
        } else {
            // Otherwise, keep the score neutral to allow opening a new bin if others are full.
            score += 5.0;
        }
    }

    // 5. Fitting Constraint:
    // If this is the last chance to fit the item (fitting_bins_count == 1), 
    // avoid opening a new bin by aggressively lowering the score of this bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Distributional Smoothing:
    // As we approach the end of the stream, prioritize clearing current bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize small, unusable gaps (Strict Dead Space Avoidance)
    // Gaps between 1 and 9 are almost always unusable given min item size 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Penalize opening new bins when space is available
    // If this is a new bin (residual == capacity) but fitting_bins_count > 0, 
    // we heavily penalize it to force usage of existing bins.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 200.0;
    }

    // 3. Lookahead: If next item fits perfectly in this residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
