        if remainder == 0 {
            score -= 40.0;
        } else if remainder < 10 {
            score += 30.0;
        }
    }

    // 4. Global pressure: As we approach the end of the stream, prioritize tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 + progress * 2.0);

    // 5. Prefer bins that keep the mean residual balanced
    // If the current bin is significantly emptier than the average, prioritize filling it.
    if bin_residual > (mean_residual as u32) {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones": if post_residual is small but > 0, 
