    }

    // 6. Progressive tightening: as the stream nears the end, become more aggressive 
    // about packing into existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

