    }

    // Lookahead logic: if next_item_size exists, penalize bins that cannot fit it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a bin that can't fit the next item
            score += 15.0;
        } else {
            // Reward bins that can accommodate the next item
            score -= 5.0;
