    // Global state optimization:
    // If we have many bins open, be more aggressive about filling existing ones
    // If fitting_bins_count is 1, this is the only bin that can take it, lower the cost to ensure we don't open a new one unnecessarily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // Smoothness: penalize bins that deviate significantly from the mean residual
    // This encourages leveling the load across all open bins
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * deviation;

    // Final adjustment to prevent creating extremely small gaps (e.g., 1-5 units)
