    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // Penalize empty bin opening using a non-linear growth function relative to progress.
    // As we approach the end of the stream, we become more conservative about opening new bins.
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post * (1.0 + (mean_residual / bin_capacity as f64));

    if is_new_bin {
        // New bin penalty: Higher if there are other bins that could fit the item.
        // We scale this penalty by (1.0 - progress) to encourage packing density early
        // and force consolidation as we near the end of the item stream.
        let penalty = (bin_capacity as f64 * 1.5) * (1.0 - progress).powf(0.5);
        score += penalty;
    } else {
        // Reward placements that leave a residual size close to the next_item_size.
        // This is a lookahead heuristic to prevent fragmentation.
        if next_item_size > 0 {
            let diff = (post - next_item_size as f64).abs();
            score -= (bin_capacity as f64 - diff) * 0.2;
        }

