    // 2. Lookahead optimization: If a next_item exists, penalize bins that cannot fit it 
    // after the current placement.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open bin pressure: Penalize opening a new bin (where bin_residual == bin_capacity)
    // unless the current open bins are extremely crowded.
    if bin_residual == bin_capacity {
        // If we have very few bins open, we are more willing to open a new one.
        // If we have many bins open, penalize opening a new one to encourage consolidation.
        score += (open_bins_count as f64) * 8.0;

        // If there are existing bins that can fit the item, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Global balance: If the mean residual of current bins is high, prefer filling existing 
    // bins rather than starting new ones to keep the "fill density" high.
    if mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 5. Progression awareness: Towards the end of the stream, prioritize closing bins
    // (lower post_residual) over keeping bins open.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
