pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // Penalize large post_residual (wasted space) quadratically.
    let mut score = post * post / capacity;

    // Penalty for opening a new bin:
    // If bin_residual == bin_capacity, it is a new bin candidate.
    // We only open a new bin if the score is lower than existing fits.
    if bin_residual == bin_capacity {
