        // to handle the end-of-stream cleanup phase.
        score += (capacity * 0.45) * (1.0 - (progress * 0.5));
    } else {
        // Favor bins that leave residual space matching the likely next item size.
        // This is a "lookahead" coupling.
        if next_item_size > 0 {
            let diff = (post - next_item_size as f64).abs();
            score -= (1.0 / (1.0 + diff)) * 15.0;
        }

        // Penalty for bins that have very small residuals ("slivers") that are 
        // statistically difficult to fill later in the stream.
        if post > 0.0 && post < 15.0 {
            score += 12.0 * (1.0 - (post / 15.0));
        }

        // Coupling with global state: 
        // Penalize deviations from the mean_residual to keep bin usage uniform.
        let dev = (post - mean_residual).abs();
        score += dev * 0.1;
    }

    // Heuristic pressure: If this is the last fitting bin, prioritize filling it
    // to prevent the need for a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
