    }

    // 5. Mean residual balancing: Penalize bins that deviate significantly from 
    // the average usage, promoting uniform packing density.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 6. Harmonic Class Logic: Reward residuals that are multiples of 20 
    // (likely to accommodate common item sizes like 20, 40, 50).
    if post_residual > 0 && post_residual % 20 == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
