    // We penalize residuals < 15, but scale this penalty by the progress of the stream.
    // Near the end of the stream, we are more desperate to pack items, so we reduce the fragment penalty.
    if !is_new_bin && post_residual < 15 {
        score += (15.0 - post_residual as f64) * (1.0 + progress);
    }

    // Lookahead logic: If the next item is large and the current placement creates a tight fit
    // that makes it impossible to fit the next item, we penalize this placement.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // If this is the only bin that fits, we heavily reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // If this is a new bin, we apply a dynamic cost that increases as we reach the end of the stream.
    // This forces the algorithm to utilize existing bins more aggressively as the stream progresses.
    if is_new_bin {
        score += 25.0 + (progress * 40.0);

        // If we have many open bins, opening a new one is more expensive.
        score += open_bins_count as f64 * 2.0;
    }

    // Reward bins that have residuals close to the mean, promoting balanced bin filling.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

