    } else {
        // Favor bins that are already partially full to consolidate
        score -= (bin_capacity - bin_residual) as f64 * 0.05;

        // If this is the last chance to fit the item, give it a significant boost
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Penalize excessive open bin count as the stream nears completion
    score += (open_bins_count as f64) * progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual. 
    // Lower residual (tighter fit) is generally better.
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' (small residuals that are hard to fill).
    // If post_residual is in the range (0, 10), it's highly undesirable.
    if !is_new_bin && post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if the next item could potentially fit into this bin's post_residual,
    // we reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (1.0 - progress);
    }

    // Dynamic thresholding: as the stream nears the end, prioritize closing bins
    // by penalizing the opening of new bins unless necessary.
    if is_new_bin {
        let open_penalty = 20.0 + (progress * 40.0) + (open_bins_count as f64 * 0.5);
        score += open_penalty;
    } else {
        // If this is the only bin that fits the item, make it very attractive.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }

        // Encourage balanced filling: penalize bins that deviate significantly from the mean residual.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize small "dead" residuals that cannot fit common item sizes.
    // Residuals < 10 are often wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If next_item fits in the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Density Balancing: If we are forced to open a new bin, penalize it based on 
    // the current mean_residual to prevent fragmenting space across too many bins.
    if bin_residual == bin_capacity {
        score += mean_residual * 0.5;
