        if fitting_bins_count > 0 && step_index < total_items {
            score += 40.0;
        }
    }

    // 4. Harmonic Alignment: Favor post_residuals that are multiples of 10 or 25, 
    // as these align with common item distributions (10, 20, 25, 50).
    if post_residual % 10 == 0 {
        score -= 5.0;
    }
    if post_residual % 25 == 0 {
        score -= 10.0;
    }

    // 5. Progression weighting: As the stream nears the end, prioritize tight packing (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 15.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

