    if post > 0.0 && post < 10.0 {
        score += 50.0 / post;
    }

    // 3. Lookahead Awareness:
    // If we have a next item, penalize bins that leave a residual smaller than the next item
    // but larger than 0 (creating a "stranded" bin).
    if next_item_size > 0 {
        if post > 0.0 && post < next_item_size as f64 {
