    if bin_residual == bin_capacity {
        // High penalty for opening new bins; reduces as we reach the end of the stream
        // to ensure we don't leave items stranded.
        score += 40.0 * (1.0 - (progress * 0.5));
    }

    // 5. Fragmentation control:
    // Penalize bins that deviate significantly from the mean_residual of other bins.
    // This encourages "leveling" the residuals across the set.
    score += (post - mean_residual).abs() * 0.5;

    // 6. Last-Chance Logic:
    // If this is the only bin that can fit the item, prioritize it significantly
    // to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
