pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity) increasingly as the stream progresses
    // to force consolidation towards the end.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (25.0 + 50.0 * progress);

    // Prioritize tighter fits (Best Fit principle). 
    // We use a non-linear scaling of post_residual to favor smaller gaps.
    let fit_score = post_res * (1.0 + 0.5 * (post_res / bin_capacity as f64));

    // Lookahead interaction: if next_item_size is large, penalize leaving a tiny residual
    // that won't be useful later. If post_residual is small but > 0, it's often a "dead zone".
    let lookahead_penalty = if next_item_size > 0 && post_res < next_item_size as f64 && post_res > 0.0 {
        (next_item_size as f64 - post_res) * 0.8
