    // Global density awareness: if we have many bins open, penalize creating more aggressively.
    let density_penalty = (open_bins_count as f64 - mean_residual / 10.0).max(0.0) * 2.0;

    // Combine terms:
    // fit_score (base) + new_bin_penalty (dynamic) + lookahead_penalty (local) + density_penalty (global)
    score = fit_score + new_bin_penalty + lookahead_penalty + density_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
