    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 4. Capacity Fraction: Penalize bins that deviate significantly from the mean residual.
    // This helps keep bins balanced in their remaining capacity.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Progression Weighting: As the stream nears completion, become more aggressive
    // about packing tightly into existing bins to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity && progress > 0.5 {
        score += 30.0 * progress;
    }

    // 6. Modulo Harmonic Bias: Favor residuals that are multiples of common item sizes (e.g., 20, 25).
    if post_residual % 20 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is too small to fit any common item 
    // (assuming 10 is the lower bound), it creates a "sliver" that is likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item can fit perfectly or near-perfectly 
    // into the remaining space, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_gap = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_gap) * 0.5;
    }

    // 3. Global Pressure: Penalize opening new bins when many are already open,
    // but reward opening a new bin if the current fit is extremely poor (large residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High penalty for opening a new bin unless existing bins are very full.
        score += (open_bins_count as f64) * 15.0;
        score -= (mean_residual * 0.2);
    } else {
        // Encourage using existing bins that have large residuals to avoid fragmentation.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Scarcity/Bottleneck: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid unnecessary bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // 5. Progression: As the stream nears the end, prioritize packing tightly 
    // to close out bins (reduce residual variance).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
