    // Dynamic adaptation: As the stream progresses, prioritize filling bins more tightly 
    // to avoid leaving many bins partially filled near the end.
    let tightness_factor = 1.0 + (progress * 2.0);
    score *= tightness_factor;

    // Favor bins that are already open over opening a new bin.
    // If this is a new bin (bin_residual == bin_capacity), add a significant penalty.
    if bin_residual == bin_capacity && open_bins_count > 0 {
