        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // reward this placement to keep the "future" bin open.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Penalize opening new bins when current bins are available,
    // but reward opening a new bin if the current fit is extremely poor (large waste).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalty for opening a new bin: base cost + scaling with existing bin count.
        score += 40.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Reward filling existing bins to minimize total count.
        score -= (open_bins_count as f64 * 0.5);
    }

    // 4. Tightness Optimization: If this is the last fitting bin, prioritize it 
    // to prevent forcing a new bin for the next item.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive
    // about filling existing bins (minimizing total bins).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

