    // 5. Balance residuals: If the bin's post_residual is significantly higher than
    // the global mean_residual, it is a "loose" bin. Penalize it to favor "tighter" bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

