    let mut score = consolidation_factor + sliver_penalty + lookahead_penalty + new_bin_penalty;

    // Favor bins that are already "half-full" to keep future options open, 
    // but only if it doesn't conflict with Best-Fit too heavily.
    score -= (bin_capacity as f64 - post) * 0.1 * (1.0 - progress);

