    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (bin_capacity - post_residual) as f64 * 1.2;
    }

    // 3. Penalty for opening new bins: Only open a new bin if the current fit is extremely poor
    // or if we are forced to.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Heavily penalize opening a new bin unless it's the only option
            score += 150.0;
        }
    }

    // 4. Entropy control: If the current residual is significantly lower than the mean_residual,
    // we are likely creating an 'orphan' bin that will be hard to fill later. Penalize this.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 20.0;
    }

    // 5. Urgency factor: If this is the last bin that can fit the item, prioritize it
    // to avoid unnecessary bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Progressive tightening: As the stream nears the end, prioritize filling
    // existing bins over starting new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
