        }
    }

    // Global state awareness:
    // If we have many open bins, penalize opening more unless the fit is very tight.
    // If we have few open bins, we can be more selective.
    score += (open_bins_count as f64) * 0.5;

    // If this is the only bin that can fit the item, we are forced to use it.
