    if !is_new_bin && fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Adjust score based on how the current bin compares to the mean residual of all open bins.
    // This helps prioritize bins that are already "below average" in terms of fragmentation.
    if !is_new_bin {
