pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize empty bin creation heavily early on, but allow flexibility as the stream ends.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 50.0 + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Calculate "fit tightness": smaller post_residual is usually better, but we want to avoid
    // creating "dead zones" (residuals < 10) that cannot fit future items.
    // If post_residual is < 10, it is a high-risk zone unless it is exactly 0.
    let dead_zone_penalty = if post_residual > 0 && post_residual < 10 {
        25.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Use lookahead: if next_item_size is large, prioritize bins that keep enough space.
    // If the next item is large (e.g., > 50), penalize bins that would leave little room.
    let lookahead_penalty = if next_item_size > 0 {
        let potential_next_res = post_res - next_item_size as f64;
        if potential_next_res < 0.0 {
            // This bin will likely not fit the next item, penalize if it's the only option
            15.0 * (1.0 - progress)
        } else {
            // Reward bins that can accommodate the next item
            -10.0 * (next_item_size as f64 / 100.0)
        }
    } else {
        0.0
    };

    // Factor in mean_residual to balance the load across open bins.
    let load_balancing = (post_res - mean_residual).abs() * 0.1;

    // Final score: prioritize tight fit (post_res) while adjusting for constraints.
    let score = post_res + new_bin_penalty + dead_zone_penalty + lookahead_penalty + load_balancing;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
