            score += 40.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0; // Otherwise, force open a new bin if nothing else fits
        }
    }

    // 5. Mean residual balancing:
    // If this bin's post_residual is significantly worse than the current mean, 
    // penalize it to encourage balancing the fill across all bins.
    if (post_residual as f64) > mean_residual {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit common items
    // (1..10) is the danger zone for standard distributions.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // 2. Lookahead Coupling: If next_item_size is large, favor bins that can accommodate it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 35.0;
    }

    // 3. Open Bins Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), penalize based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // If there are other bins that could fit the item, strongly discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Mean Residual Balancing: Favor bins that align with the current global state.
    // This pushes the heuristic toward Best Fit behavior by penalizing deviations from the mean.
    score += ((post_residual as f64) - mean_residual).abs() * 0.2;

    // 5. Progression Weighting: As the stream nears the end, prioritize tight packing (lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0) * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We want post_residual to be as small as possible.

    // 2. Lookahead Synergy: If the post_residual matches the next item size, 
    // it's an ideal placement. Reward this heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= 50.0 / (1.0 + diff);
    }

    // 3. New Bin Thresholding: Penalize opening a new bin unless the current
    // fitting bins are forcing a very poor fit (large post_residual).
    if bin_residual == bin_capacity {
        // If we open a new bin, we want it to be justified by high fragmentation elsewhere.
        // Penalty is proportional to the average slack currently available.
        score += mean_residual * 0.8;

        // If there are other bins that could fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    } else {
        // 4. Fragmentation Control: If this bin becomes very tight, prioritize it.
        // If it leaves a "sliver" (e.g., 1-5 units), it's often worse than leaving 10-20.
        if post_residual > 0 && post_residual < 8 {
            score += 15.0; // Penalty for creating unusable space
        }
    }

    // 5. Progression Scaling: As the stream nears the end, be more aggressive
    // about filling existing bins to reduce the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. 
    // We prioritize Best-Fit (smallest post_residual) but penalize creating "fragmented" bins 
    // that are too small for common item sizes or the lookahead item.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score is the residual space (Best-Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating a new bin: only do this if it's the only option or if 
    // existing bins are very poorly suited (based on mean_residual).
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one fits
            score += 45.0 + (mean_residual * 0.5);
        } else {
            // If no other options, prioritize the new bin
            score -= 10.0;
        }
    } else {
        // Lookahead heuristic: If the next item fits into the current post_residual, 
        // we reward this placement to encourage "packing pairs".
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }

        // Penalty for "fragmentation": creating a residual that is too small for most items (e.g., < 15)
        // unless it is exactly 0 (a perfect fit).
        if post_residual > 0 && post_residual < 15 {
            score += 15.0 - (post_residual as f64 * 0.5);
        }
    }

    // Dynamic horizon adjustment: As we reach the end of the stream, 
    // become more aggressive in filling bins to prevent straggler items.
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // Global state pressure: if we have too many open bins, penalize keeping more open
    score += (open_bins_count as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize opening new bins early in the stream, but allow flexibility near the end.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 50.0 + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Calculate a "tightness" factor. Prefer bins where the post_residual is small
    // (Best Fit principle) but penalize tiny residuals that leave "dead space" (e.g., < 10)
    // that cannot accommodate future items.
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        (10.0 - post_res) * 5.0
    } else {
        0.0
    };

    // Incorporate lookahead: if next_item_size is large, favor bins with larger post_residual
    // to accommodate the upcoming demand.
    let lookahead_score = if next_item_size > 0 {
        let needed = next_item_size as f64;
        if post_res < needed {
            (needed - post_res) * 2.5
        } else {
            -(post_res - needed) * 0.5
        }
    } else {
        0.0
    };

    // Balance the mean residual: discourage creating bins that deviate significantly
    // from the average performance of current bins to keep bin utilization uniform.
    let uniformity_penalty = (post_res - mean_residual).abs() * 0.5;

    // Final score: prioritize lowest result.
    // Base score is post_residual (Best Fit).
    post_res + new_bin_penalty + dead_space_penalty + lookahead_score + uniformity_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
