    }

    // 2. Harmonic Class Logic: Reward bins that align with modulo-based bin fractions.
    // We prioritize keeping residuals as multiples of common item sizes (e.g., 20, 25, 50).
    let alignment = (post_residual % 25) as f64;
    score += alignment * 0.5;

    // 3. Lookahead Logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
