    score += (post_residual as f64) * 0.1;

    // 2. Penalty for creating "unusable" space (1..9 range).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0; 
    }

    // 3. Lookahead integration: If the next item is large and won't fit in the current residual,
    // we should prioritize bins that leave enough room for it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize this bin if it makes the next item impossible to fit here,
            // unless this bin is already nearly full or we have many open bins.
            score += (next_item_size - post_residual) as f64 * 0.5;
        } else {
            // Reward this bin if it perfectly accommodates the next item.
            score -= (next_item_size as f64) * 0.2;
        }
    }

    // 4. Global state: If we have many open bins, penalize opening a new one.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalty for opening a new bin scales with current open bin count.
        score += (open_bins_count as f64) * 15.0;

        // If it's the last item, opening a new bin is always bad.
        if step_index == total_items - 1 {
            score += 1000.0;
        }
    }

    // 5. Fitting constraint: If only one bin can fit the item, prioritize it heavily
    // to avoid unnecessary bin proliferation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // 6. Dynamic horizon: As we approach the end of the stream, prioritize tight packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (mean_residual * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space. 
    // We aim to minimize this (Best Fit principle).
    let mut score = post_res;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We define "dead" as < 10, which is the minimum possible item size.
    if post_res > 0.0 && post_res < 10.0 {
        score += (10.0 - post_res) * 5.0;
    }

    // Lookahead coupling: If the next item cannot fit in this post_residual, 
    // penalize this bin choice to encourage keeping the space open for the next item.
    if next_item_size > 0 && post_res < next_item_size as f64 {
        score += (next_item_size as f64 - post_res) * 2.5;
    }

    // Progression adjustment: As the stream nears completion, 
    // become more aggressive in filling bins to capacity (Best Fit).
    // Early in the stream, be more conservative to avoid fragmentation.
    score += (1.0 - progress) * (bin_residual as f64 / 4.0);

    // If this is a new bin, apply a significant penalty to encourage using existing bins,
    // but scale the penalty down as the stream progresses to allow for better packing 
    // when existing bins are poorly suited for remaining items.
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - (progress * 0.5));
    }

    // If this is the only bin that can fit the item, reward it to prevent unnecessary 
    // bin proliferation (prioritize closing existing bins).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize high variance in bin utilization by comparing this bin's residual 
    // to the mean_residual of all open bins.
    score += (post_res - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
