    // 2. Lookahead Synergy: If the next item can fit perfectly or near-perfectly into the current post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap_after_next = post_residual - next_item_size;
        // Reward if the next item leaves a very small gap or fills it completely (0-5 range)
        if gap_after_next < 5 {
            score -= 30.0;
        }
    }

    // 3. Open Bins Pressure: Penalize opening a new bin if other bins are available
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Only open a new bin if existing bins are already "full enough" (mean_residual is low)
        // or if we have too many open bins already (to encourage consolidation).
        if open_bins_count > 0 {
            score += 40.0 + (mean_residual * 0.5);
        }
    } else {
        // Existing bin bonus: Prefer bins that are already partially filled to keep the open bin count low
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Scarcity/Fitting constraint: If this is the last chance to fit the item in an existing bin,
    // reduce the penalty for a poor fit to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
