        score += progress * 20.0;
    }

    // 4. Global State Awareness: If we have many open bins, penalize opening more.
    // If we have very few bins, favor spreading items to keep residuals high for future large items.
    score += (open_bins_count as f64) * 2.5;

    // 5. Mean Residual Balancing: If the current bin is 'tighter' than the average,
    // it is a good candidate for the current item to keep the average stable.
    let residual_delta = (bin_residual as f64) - mean_residual;
    score += residual_delta * 0.5;

    // 6. Last Chance Logic: If this is the only bin that fits the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity) using a dynamic threshold 
    // that scales with the progression and the current packing efficiency (mean_residual).
    let is_new_bin = bin_residual == bin_capacity;
    let base_penalty = if is_new_bin {
        // As the stream progresses, make opening a new bin increasingly expensive 
        // unless the average residual space is high (indicating poor packing).
        (1.0 - progress) * 40.0 + (mean_residual * 0.5)
    } else {
        0.0
    };

    // Non-linear coupling: reward post-residuals that are small (Best Fit),
    // but penalize those that are "too small" to fit the next item (lookahead).
    // If next_item_size > post_residual, it creates "dead space" that cannot be used by the next item.
    let mut lookahead_penalty = 0.0;
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a hole smaller than the next item
            lookahead_penalty = (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward creating a hole that perfectly accommodates the next item
            lookahead_penalty = -((post_residual - next_item_size) as f64).sqrt() * 2.0;
        }
    }

    // Fitting bin heuristic: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    let scarcity_bonus = if fitting_bins_count == 1 && !is_new_bin {
        -50.0
    } else {
        0.0
    };

    // Combine factors:
    // 1. post: Best Fit logic (smaller is better)
    // 2. base_penalty: Discourage new bins late in the stream
    // 3. lookahead_penalty: Optimize for future item geometry
    // 4. scarcity_bonus: Protect the last viable bin
    post + base_penalty + lookahead_penalty + scarcity_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals to keep bins tightly packed.
    // We favor post_residuals that are small (close to 0).
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic: If post_residual is small but not zero, it creates "dead space".
    // Penalize small remainders that are unlikely to accommodate the next item.
    if post_residual > 0 && post_residual < next_item_size {
