        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: Reward bins where the post_residual can fit the next item perfectly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact matches or tight fits for the next item
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 0.5;
        } else {
            // Penalize if the current bin won't fit the next item when it could have
            score += 20.0;
        }
    }

    // 3. New Bin Threshold: Discourage opening new bins unless the fit is extremely poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High base cost for opening a new bin, reduced by the progress of the stream.
        let progress = step_index as f64 / total_items as f64;
        score = 85.0 - (progress * 20.0);
    }

    // 4. Mean Residual Balancing: Favor bins that stay near the global mean to keep
    // future packing options uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Last Chance Logic: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins packed tightly.
    // However, we reward 'perfect fits' (post_residual == 0).
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // prioritize this bin to prevent fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Dynamic Thresholding for New Bins:
    // When we are near the end of the stream, be more aggressive with packing.
    // When we have many open bins, penalize opening new ones significantly.
    if is_new_bin {
        // Base penalty for opening a new bin
        score += 45.0 + (open_bins_count as f64 * 2.0);

        // If we are late in the stream, increase the penalty to force consolidation
        score += progress * 30.0;
    } else {
        // 4. Global State Awareness:
        // If this bin is the only one that fits, give it a slight boost to ensure it's used.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }

        // 5. Fragmentation Avoidance:
        // Penalize residuals that are too small to be useful for future items (e.g., < 10)
        // unless they are exactly 0.
        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }
    }

    // 6. Mean Residual Balancing:
    // Avoid bins that deviate too far from the current average residual to keep
    // bin states somewhat uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space after placement
    let mut score = post_res;

    // Penalty for creating a 'bad' residual that is too small for common items but too large for efficiency.
    // We prioritize bins that leave exactly 0 space (Best Fit) or leave enough room for a likely next item.
    if post_residual > 0 {
        // Reward if the bin can accommodate the next item (lookahead benefit)
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
        }

        // Penalize residuals that are small but unusable (1-9 range)
        if post_residual < 10 {
            score += 15.0 * (1.0 - (post_res / 10.0));
        }
    }

    // Dynamic pressure: As the stream progresses, be more conservative about opening new bins.
    // If this is a new bin (bin_residual == bin_capacity), increase its cost significantly as we approach the end.
    if bin_residual == bin_capacity {
        score += 20.0 + (progress * 50.0);

        // If there are existing bins that could fit the item, penalize opening a new one heavily.
        if fitting_bins_count > 0 {
            score += 40.0 * (1.0 - progress);
        }
    }

    // Coupling: If the mean residual of current bins is high, prefer filling those up 
    // to keep the average bin usage tight.
    if mean_residual > post_res {
        score -= (mean_residual - post_res) * 0.5;
    }

    // Final adjustment: Favor bins that result in a 'clean' fit relative to the bin capacity
    // based on the current step progress to encourage packing density.
    score += (post_res / bin_capacity as f64) * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger post_residuals.
    // We want the post_residual to be as close to 0 as possible.
    score += post_residual as f64 * 1.5;

    // 2. Harmonic Class Logic: Reward placements that leave residuals divisible by common item sizes.
    // This creates "bins of specific sizes" for future items.
    if post_residual > 0 {
        score -= (post_residual % 10) as f64 * 2.5;
        score -= (post_residual % 25) as f64 * 0.5;
    }

    // 3. Lookahead Integration: If the next item fits into the post_residual, 
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && next_item_size <= post_residual {
