        // Bonus for leaving a tight remainder after the next item
        score -= (post_residual - next_item_size) as f64 * 0.8;
    }

    // 4. New Bin Threshold: Discourage opening new bins unless the current fit is extremely poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if we have many open bins already or if the average 
        // residual is high (meaning existing bins are already poorly packed).
        score += 85.0;
        score -= (open_bins_count as f64) * 0.5;
        score += mean_residual * 0.5;
    } else {
        // If this is the last chance to fit the item in existing bins, prioritize it.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // 5. Progression Weighting: As the stream nears completion, become more aggressive 
    // about fitting items into existing bins to avoid stragglers.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are likely unusable (below 10).
    // If post_residual is in (0, 10), it's highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // Reward tighter fits: Prefer bins where the post_residual is closer to 0.
