    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64) * 25.0;
        // As the stream nears the end, increase penalty for opening new bins.
        score += (step_index as f64 / total_items as f64) * 30.0;
    }

    // Efficiency bias: Penalize bins that deviate significantly from the mean_residual
    // to keep the bin distribution uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that is too small for common future items.
    // If the post-residual is smaller than the next item, we penalize it unless it's zero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
