        score += (open_bins_count as f64) * 0.5;
    }

    // 4. Lookahead coupling: If post_residual is perfectly sized for the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let waste_after_next = (post_residual - next_item_size) as f64;
        // Small waste is good, large waste is bad.
        score += waste_after_next * 0.2;
    }

    // 5. Mean residual balancing: Prefer bins that stay close to the average state of the system.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.1;

    // 6. Urgency: If this is the last chance for this item, reduce penalty to avoid overflowing.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Target: Best-Fit Decreasing logic modulated by lookahead (next_item_size) and stream progression.
    // We aim to minimize the post_residual (tightest fit), but penalize creating "orphaned" space
    // that cannot accommodate the next known item.

    let mut score = post_residual as f64;

