    // 3. Global state: If we are late in the stream, prioritize closing bins (lower mean_residual).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Late game: aggressively fill bins to consolidate
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    // 4. Fitting count penalty: If this is the only bin that can fit the item,
    // prioritize it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Penalize creating very small, unusable slivers (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
