    // If post_residual is small but > 0, it's often a "dead zone". 
    // We penalize values < 10 (common minimum item size is 1).
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead coupling: If the next item is large, favor bins that can accommodate it.
    // If post_residual is less than next_item_size, we penalize the bin proportionally 
    // to the lookahead size to encourage keeping space for the next item.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Dynamic pressure based on stream progression:
    // As we approach the end of the stream, prioritize filling existing bins 
    // over opening new ones to minimize total bin count.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // As progress increases, the penalty for opening a new bin grows non-linearly.
        score += 20.0 * (1.0 + progress.powf(2.0));

        // If there are other bins that could fit this item, strongly penalize opening a new one.
        if fitting_bins_count > 0 {
