    // Only open a new bin if the current fitting options are extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0; // Necessary, make it attractive.
        } else {
            // Heavily penalize opening a new bin if an existing bin could fit the item.
            score += 45.0 + (open_bins_count as f64 * 0.5);
        }
    }

    // 5. Progression weighting: As the stream nears the end, be more aggressive to finish bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit logic: prioritize bins that leave the least space (lower post_residual is better).
    // The base score already accounts for this.

    // 2. Penalty for creating "slivers" (unusable space < 10): 
    // If post_residual is between 1 and 9, it's a "dead space" trap.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 3. Lookahead integration:
    // If we have a next item, penalize current bin if it cannot fit the next item after this one.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress); 
        } else {
            // Reward bins that can accommodate the next item (synergy).
            score -= 15.0 * (1.0 - progress);
        }
    }

    // 4. Global state pressure:
    // If fitting_bins_count is 1, we are forced to pick this bin or open a new one.
    // If we are opening a new bin, penalize it based on how much space we waste relative to the mean.
    if is_new_bin {
        if open_bins_count > 0 {
            // Only open a new bin if the mean residual is high enough that we aren't just wasting space.
            score += 30.0 + (mean_residual * 0.5);
        } else {
            // Opening the first bin is always necessary.
            score -= 100.0;
        }
    } else {
        // Encourage using existing bins that align with the global average efficiency.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 5. Late-stage urgency:
    // As we approach the end of the stream, prioritize closing bins (lower residuals).
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space after placement. 
    // Minimizing this naturally pushes towards Best-Fit behavior.
    let mut score = post_res;

    // Penalty for creating 'dead zones' (small residuals < 10) that are hard to fill later.
    // This penalty scales with progress to be more conservative as the stream nears the end.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_res) * (1.0 + progress * 2.0);
    }

    // Lookahead logic: If the next item could fit in the current post_residual, 
    // reward this bin to keep the next item's space available.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    }

    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily early on,
    // but relax the penalty as the stream progresses to allow for better packing configurations 
    // when existing bins are already suboptimal (high mean_residual).
    if bin_residual == bin_capacity {
        let new_bin_penalty = 40.0 * (1.0 - progress) + (mean_residual * 0.2);
        score += new_bin_penalty;
    }

    // If this is the only bin that can fit the item, we are forced to pick it;
    // slightly reward it to ensure it is prioritized over opening a new bin if possible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Interaction term: penalize bins that deviate significantly from the mean_residual
    // to keep the packing density uniform across all active bins.
    let dev = (post_res - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "unusable" small gaps (1-9) which are hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if next item is large, prioritize bins that keep a larger post_residual
    // otherwise, prioritize tight fits to minimize wasted space.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This bin will be unable to fit the next item; penalize if we have other options
            score += 25.0;
        } else {
            // This bin can fit the next item; reward
            score -= 10.0;
        }
    }

    // Heuristic: If we are forced into a new bin (bin_residual == bin_capacity), 
    // heavily penalize it unless fitting_bins_count is 0 or we are near the end of the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // Harmonic/Modulo influence: Favor bins where the post_residual is a multiple of 10
    // as these are more likely to accommodate future items in a standard distribution.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    // Penalty for creating too many open bins relative to the mean residual
    if open_bins_count as f64 > (100.0 / (mean_residual + 0.1)) {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "dead space": If the post_residual is too small to fit typical items (< 10),
    // it creates a fragment. We penalize this heavily unless it's a perfect fit (post_residual == 0).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead optimization: If the next item is large, favor bins that can accommodate it.
    // If post_residual cannot fit the next item, we add a penalty.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 3. Global Bin Pressure: If we have many open bins, prioritize filling them tightly 
    // to avoid opening new ones. If we have few, we are more flexible.
    score += (open_bins_count as f64) * 0.5;

    // 4. New Bin Logic: If this is an empty bin (new bin candidate), 
    // only choose it if the penalty of forcing a fit into existing bins is massive.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average waste in existing bins is already high,
        // or if we have very few open bins (avoiding fragmentation early).
        score = 45.0 + (open_bins_count as f64 * 2.0) - (mean_residual * 0.5);
    } else {
        // If it's a tight fit (fitting_bins_count == 1), reward it to prevent 
        // leaving the bin "stranded" with a small residual.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // 5. Progression scaling: As we approach the end of the stream, 
    // prioritize closing existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // but reward configurations that leave a residual close to the lookahead item.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward if post_residual can perfectly accommodate the next item
        if post_residual >= next_item_size {
            score -= (100.0 - diff) * 0.5;
        } else {
            // Penalize if post_residual is too small to fit the next item effectively
            score += diff * 0.8;
        }
    }

    // 2. Penalize opening new bins unless necessary
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0 * (1.0 - progress); // High penalty for opening new bin early
        }
    }

    // 3. Balance the load: penalize bins that deviate too far from the mean residual
    // This promotes "leveling" the bins to keep options open for future items.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.3;

    // 4. Critical threshold for "last chance" bins
    // If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Prefer tighter fits as the sequence nears completion
    score += (post_residual as f64) * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
