    // 3. Harmonic-style penalty: penalize small remainders that cannot fit likely future items.
    // Small remainders (1-9) are usually "dead space" unless they are zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Threshold logic: if this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
