}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (dead space < 10) exponentially as they are hard to fill
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post).powi(3)
    } else {
        0.0
    };

    // Reward utilizing bins that are already "tight" to keep them tight, 
    // but balance this against the need to reserve space for future large items.
    let lookahead_factor = if next_item_size > 0 {
        let fit_next = if post >= next_item_size as f64 { 1.0 } else { 0.0 };
        (1.0 - fit_next) * (next_item_size as f64 * 0.5)
    } else {
        0.0
    };

    // If it's a new bin, penalize based on progress. Later in the stream, 
    // we are more desperate to avoid opening new bins.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (50.0 * (1.0 + progress)).powi(2)
    } else {
        0.0
    };

    // Prefer bins that stay close to the current mean residual to maintain packing uniformity
    let deviation_penalty = (post - mean_residual).abs() * 0.5;

    // Favor bins that are the last chance (fitting_bins_count == 1) to avoid opening a new one,
    // unless the fit is extremely poor (post_residual < 5).
    let desperation_bonus = if fitting_bins_count == 1 && post >= 5.0 {
        -50.0
    } else {
        0.0
    };

    let score = post + dead_space_penalty + lookahead_factor + new_bin_penalty + deviation_penalty + desperation_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
