    // as this creates "fragmentation" (dead space that cannot fit the next item).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 150.0 * (1.0 - (post_res / next_item_size as f64));
        }
    }

    // Avoid excessive open bins:
    // If we have many open bins, penalize the creation of new ones or picking bins that 
    // contribute to a fragmented state (high mean_residual).
    score += (open_bins_count as f64 * 0.5) * (mean_residual / bin_capacity as f64);

    // Final adjustment:
    // If this is the last chance for the item (fitting_bins_count == 1), 
    // significantly reward the bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // We use a non-linear weight to strongly discourage leaving large gaps.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: If post_residual is small (e.g., < 20), reward it 
    // as it creates "perfect" fit potential for subsequent items.
    if post_residual < 20 {
        score -= 50.0 * (1.0 - (post_residual as f64 / 20.0));
    }

    // 3. Lookahead Synergy: If the next item fits into the current post_residual, 
    // strongly reward this bin to avoid fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 120.0;
        // Further refine: reward bins that leave a small remainder for the next item
        let synergy = post_residual - next_item_size;
        score += synergy as f64 * 0.5;
    }

    // 4. Thresholding for New Bin Creation:
    // If bin_residual == bin_capacity, this is a new bin. 
    // Only open a new bin if we have no good fits (high fitting_bins_count) 
    // or if the current mean_residual is already very high (wasted space).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0; // Forced to open a new bin
        } else {
            // Heavily penalize opening a new bin if existing ones can fit the item
            score += 200.0 + (mean_residual * 2.0);
        }
    }

    // 5. Progression Scaling:
    // As the stream progresses, become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 30.0 * (open_bins_count as f64);

    // 6. Harmonic Modulo Constraint:
    // If the post_residual creates a common divisor with the capacity (e.g., 20, 25, 50),
    // it's statistically more likely to fit future items.
    if post_residual > 0 && (bin_capacity % post_residual == 0) {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residuals that are too small to fit common items (below 10)
    // but large enough to be "wasted" (between 1 and 9).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item can fit in the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bins Pressure: Discourage opening new bins if we have many already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += (open_bins_count as f64) * 2.5;
    } else {
        // 4. Tightness Reward: Favor bins that become very full (Best Fit principle).
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // 5. Last Chance Logic: If this is the only bin that can fit the item, prioritize it 
    // to avoid potential spillover, unless it creates a highly inefficient gap.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // 6. Global Efficiency: If the post_residual is exactly 0, it's a perfect fit.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Archetype: Aggressive Best-Fit with 2-step Lookahead (Best-Fit Decreasing logic).

    let mut score = post_residual as f64;

    // 1. Penalty for creating "slivers" (dead space < 10):
    // Slivers are hard to fill with items (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization:
    // If we have a next item, favor bins where the post_residual can fit it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact or near-exact matches for the next item.
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving a gap that cannot fit the next item if we have other options.
            score += 15.0;
        }
    }

    // 3. Pressure to consolidate:
    // If this is the last chance for the current item (fitting_bins_count == 1), 
    // heavily reward placing it here to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 4. New Bin Management:
    // If we are considering a new bin (bin_residual == bin_capacity), penalize it 
    // unless the fit in existing bins is extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high.
        score += 65.0;
        // Dynamically lower the penalty if open bins are very crowded (low mean_residual).
        if mean_residual < 20.0 {
            score -= 10.0;
        }
    }

    // 5. Global density adjustment:
    // As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base cost: The post_residual is the space wasted in this bin. Lower is better (Best Fit).
    let mut score = post_residual as f64;

    // 2. Penalty for creating "dead space": If post_residual is small but not zero (e.g., 1-9),
    // it is often unusable for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead integration: If the next item can fit in the post_residual, 
    // prioritize this bin heavily to preserve space in other bins.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 4. Global state: If we have many open bins, penalize opening a new one significantly.
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 2.0);
    }

    // 5. Dynamic horizon: As we approach the end of the stream, prioritize tighter packing.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual > 20 {
        score += 10.0 * progress;
    }

    // 6. Balance the load: Penalize bins that deviate too far from the mean_residual
    // to keep bins relatively uniform in their fullness.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 7. Critical threshold: If this is the only bin that fits, prioritize it strongly
    // unless it results in a very poor fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) unless it's a perfect fit.
    // Near-zero residuals are excellent (score reduction), but very small 
    // positive residuals (1-5) are death traps.
    let fragmentation_penalty = if post == 0.0 {
        -50.0
    } else if post < 10.0 {
        25.0 / post
    } else {
        0.0
    };

    // Use lookahead to discourage opening new bins if the next item is large.
    // If next_item_size is large, we want to save space in existing bins.
    let lookahead_pressure = if next_item_size > 0 {
        (next_item_size as f64 / bin_capacity as f64) * 20.0
    } else {
        0.0
    };

    // Non-linear coupling: As the stream progresses, favor tighter packing 
    // (lower post_residual) more aggressively to avoid late-stage fragmentation.
    let progress_weight = 1.0 + (progress * 2.0);

    // Evaluate the cost of the current bin:
    // 1. Base score is the remaining space (Best Fit principle).
    // 2. Add fragmentation penalty.
    // 3. Add lookahead pressure.
    // 4. Subtract a bias for using existing bins vs opening new ones.
    let mut score = (post * progress_weight) + fragmentation_penalty + lookahead_pressure;

    // Logic for new bin candidate (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual is very high (wasteful)
        // or if we have very few options.
        let new_bin_bias = 45.0 + (mean_residual * 0.5) - (progress * 10.0);
        score += new_bin_bias;
    } else {
        // Existing bin: reward bins that are already "tight"
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
