    // 2. Penalty for creating "dead zones" (residuals too small for common items)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead logic: Reward placing an item if the post_residual 
    // can accommodate the next item (synergy).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
        } else if post_residual > 0 {
            // Penalty for blocking the next item if it could have fit elsewhere
            score += 15.0;
        }
    }

    // 4. Global state awareness:
    // If we are near the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (open_bins_count as f64 * 0.5);

    // 5. Threshold logic for new bins:
    // Only open a new bin if the current fit is extremely poor (post_residual > 40)
    // or if the residual is strictly suboptimal compared to the mean.
    if bin_residual == bin_capacity {
        if post_residual > 40 {
            score -= 10.0;
        } else {
            score += 100.0; // Heavy penalty for opening new bins unnecessarily
        }
    }

    // 6. Prefer bins that are already closer to the mean residual to keep distribution uniform
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
