        if fit_delta >= 0 && fit_delta < 5 {
            score -= 30.0; // Strong reward for potential perfect fit
        }
    }

    // Balance against open bin count to prevent excessive bin creation
    // as the stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    // Harmonic heuristic: If post_residual is a multiple of the item_size or capacity,
    // it suggests better packing density.
    if item_size > 0 && post_residual % (item_size / 2 + 1) == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "unusable" small gaps (dead space between 1 and 9).
    // Gaps smaller than the minimum possible item size (1) are impossible, 
    // but gaps < 10 are highly likely to be stranded.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Penalty for opening a new bin (bin_residual == bin_capacity)
    // We only open a new bin if the current fit is extremely inefficient (high post_residual).
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.0);
    }

    // 3. Lookahead optimization: If next_item_size is large, avoid leaving a tiny residual.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 4. Pressure: If the current bin is the *only* one that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global state normalization: Favor bins that align with the mean density 
    // to keep the bin distribution uniform.
    let density_deviation = (post_residual as f64 - mean_residual).abs();
    score += density_deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins packed tightly.
    // We weight this by the ratio of open bins to encourage consolidation.
    score += (post_residual as f64) * (open_bins_count as f64 / 10.0);

    // 2. 2-Step Lookahead: If the current placement leaves a gap that perfectly fits the next item,
    // we heavily reward that bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_waste = (post_residual - next_item_size) as f64;
        // Reward small gaps that accommodate the lookahead item.
        score -= (100.0 - gap_waste);
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the current mean residual 
    // is already very low, implying we are running out of space in existing bins.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 25.0 {
            // Penalize opening a new bin if we have plenty of space elsewhere.
            score += 150.0;
        } else {
            // Otherwise, keep it neutral/slightly positive to force usage of empty space.
            score += 40.0;
        }
    }

    // 4. Criticality: If this is the only bin that fits, prioritize it strongly
    // to avoid unnecessary fragmentation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // 5. Progression Bias: As we approach the end of the stream, prioritize 
    // closing bins (lower post_residual) more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin that is "too empty" early on, but prioritize "tight fits"
    // Best Fit Decreasing logic: penalize large post_residuals.
    // If we have a perfect fit (post_residual == 0), reward it heavily.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead logic: If the next item can fit in the current post_residual, 
    // we should prioritize bins that leave exactly enough room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = (post_residual - next_item_size) as f64;
        score += tightness * 0.5;
    } else if next_item_size > post_residual && post_residual < 20 {
        // Penalty for "stranded" space: if the remaining space is too small for common items
        score += 30.0;
    }

    // Global state awareness: If we are near the end of the stream, 
    // be more aggressive about filling existing bins rather than opening new ones.
    if fitting_bins_count > 0 && bin_residual == bin_capacity {
        // This is the "New Bin" candidate call.
        // Penalize opening a new bin heavily if we have many fitting bins.
        score += (fitting_bins_count as f64 * 40.0) * (1.0 - progress * 0.5);
    }

    // Encourage balancing residuals across open bins to avoid "bin fragmentation"
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity) increasingly as the stream progresses
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (100.0 + (progress * 200.0));

    // Favor fitting into bins that result in small residuals (Best Fit)
    // Add a non-linear penalty for creating "dead space" (residuals < 10 are often unusable)
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Lookahead coupling: if the next item is large, avoid leaving a small residual
    let lookahead_penalty = if next_item_size > 0 {
        let potential_fit = post >= next_item_size;
        if !potential_fit && post < next_item_size && post > 0.0 {
            (next_item_size as f64 - post) * 0.5
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Reward packing into bins that keep the mean residual balanced
    // This helps avoid clustering large residuals in one bin
    let imbalance_penalty = (post - mean_residual).abs() * 0.2;

    // Critical: If fitting_bins_count is 1, it's the only bin that can take it, 
    // so we strongly discourage opening a new bin by adding a high priority bonus to this bin.
    let exclusivity_bonus = if fitting_bins_count == 1 && is_new_bin == 0.0 {
        -50.0
    } else {
        0.0
    };

    let score = post + new_bin_penalty + dead_space_penalty + lookahead_penalty + imbalance_penalty + exclusivity_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Penalty: Minimize post_residual, but prioritize tight fits (near 0)
    // We heavily penalize large post_residuals that are "orphaned" (cannot fit common item sizes)
    // A post_residual < 10 is usually dead space, so we treat it as a high-cost efficiency loss
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Integration: If next_item_size is large, avoid bins that leave just enough space
    // to be "awkward" but not enough for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This bin cannot fit the next item; add penalty proportional to how close we came
            score += (next_item_size - post_residual) as f64 * 0.5;
        } else {
            // This bin CAN fit the next item; reward this placement
            score -= (bin_capacity - post_residual) as f64 * 0.2;
        }
    }

    // 3. Harmonic Load Balancing: Prevent spreading items too thin.
    // If we have many open bins, penalize opening a new one unless necessary.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 4. Mean Residual Coupling: If this bin's residual is significantly better than the mean,
    // prioritize it to keep the global average residual low.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Critical Constraint: If this is the only bin that fits, force selection
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 6. Progression Scaling: As the stream nears the end, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residuals that are too small to fit typical items (10-20)
    // but too large to be considered 'tight'. This avoids creating "sliver" gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
