        // As we approach the end of the stream, discourage opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 100.0;
    }

    // 5. Residual Balancing: Favor bins that stay near the mean_residual to keep distribution uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We already start with post_residual.

    // 2. Lookahead Synergy: If post_residual is close to next_item_size, we reward this placement.
    // The perfect match is post_residual == next_item_size (score 0), 
    // but we add a penalty for gaps that are too small to fit anything useful.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;

        // Penalize creating tiny unusable fragments (less than 10) if next_item_size is large.
        if post_residual < 10 && post_residual > 0 {
            score += 25.0;
        }
    }

    // 3. Global Efficiency: If this is a new bin, penalize it relative to how many bins are open.
    // We only want to open a new bin if the current mean_residual is already quite high,
    // indicating our current packing is inefficient.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is scaled by the existing number of bins.
        score += 40.0 + (open_bins_count as f64 * 2.0);
        // If mean_residual is high, opening a new bin is less punishing.
        score -= mean_residual * 0.5;
    } else {
        // 4. Pressure: If this is the last fitting bin, prioritize it to avoid opening new bins.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // 5. Progression: As we reach the end of the stream, prioritize closing gaps.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.1);

