        if post_residual >= next_item_size {
            // Reward exact fit or near-exact fit for the next item
            let gap = (post_residual - next_item_size) as f64;
            score -= (25.0 / (1.0 + gap));
        } else {
            // Penalize placements that leave too little space for the next item
            score += 15.0;
        }
    }

    // 3. Efficiency Balancing:
    // Avoid creating "orphan" bins by rewarding placements that align with the mean_residual
    // of currently open bins.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.2;

    // 4. Urgency/Pressure:
    // As we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // If this is the only bin that can fit the current item, prioritize it heavily.
        score -= 50.0 * (1.0 - progress);
    }

    // 5. Penalize "Dead Zones":
    // Residuals below 10 are often unusable for future items (assuming min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger post_residuals
    // (the smaller the gap left, the better the fit).
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead optimization: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize bin density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. New bin penalty: Only open a new bin if the current fit is extremely poor
    // or if we have no better options.
    if bin_residual == bin_capacity {
        // Dynamic threshold: opening a new bin becomes costlier as we near the end of the stream.
        score += 45.0 + (progress * 30.0);
    }

    // 4. Global state coupling: If we have many open bins, penalize creating more.
    score += (open_bins_count as f64) * 2.0;

    // 5. Fitting constraint: If this is the last bin that can fit the item, 
    // reduce penalty to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Mean residual balancing: Penalize bins that deviate significantly from the mean 
    // to keep bin usage balanced.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
