    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // As the stream progresses, we want to be more conservative about opening new bins.
    if is_new_bin {
        // Penalty scales with current open bins and progress to force consolidation.
        score += 40.0 + (open_bins_count as f64 * 2.0) + (progress * 30.0);
    } else {
        // Reward fitting into existing bins.
        // If this is the last fitting bin, prioritize it to avoid creating a new bin later.
        if fitting_bins_count == 1 {
