        if next_item_size > 0 {
            let space_waste = post_residual as f64;
            let lookahead_pressure = (next_item_size as f64 / (post_residual + 1) as f64).min(5.0);
            score += space_waste * lookahead_pressure * 0.5;
        }

        // Interaction with mean_residual:
        // If current bin's post_residual is significantly better than the global average, favor it.
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
