    };

    // Incorporate lookahead: if the next item is large, favor bins that leave enough space
    // If next_item_size is 0 (end of stream), ignore lookahead
    let lookahead_score = if next_item_size > 0 {
        if post < next_item_size as f64 {
            (next_item_size as f64 - post) * 2.5
        } else {
