    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. Penalty for creating "dead space": post_residuals between 1 and 9 are often unusable
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 3. Lookahead integration: If the next item fits into the current post_residual, prioritize this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 4. Global state: If many bins are open, discourage new bin creation
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5) + (1.0 - progress) * 15.0;
    }

    // 5. Dynamic horizon: As the stream nears the end, be more aggressive with fitting
    // (Reduce penalty for small post_residuals as we approach the end)
    if progress > 0.8 {
        score -= (post_residual as f64 * 0.2);
    }

    // 6. Avoid fragmentation: If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 7. Balance fill levels: Penalize bins that deviate far from the mean
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

