    // This helps prevent outlier bins (too empty or too full)
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 4. Tightness: Prefer bins that leave very little space (Best Fit variant)
    // Small post_residual is good, but we balance against potential dead space
    if post_residual < 10 {
