    // 1. Penalize "dead space": gaps smaller than the smallest likely item (10).
    // If post_residual is in (0, 10), it is highly likely to become unusable.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 15.0;
    }

    // 2. Lookahead optimization: If next_item_size is known, penalize placements 
    // that prevent the next item from fitting in the current bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Pressure management: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 4. Global bin count control: Penalize opening a new bin (bin_residual == bin_capacity)
    // as the stream progresses, unless the mean residual of existing bins is already very low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        let penalty = 30.0 + (progress * 40.0) - (mean_residual * 0.5);
        score += penalty;
    }

    // 5. Reward tight fitting: Exponentially reward smaller post_residuals 
    // to favor Best-Fit behavior over First-Fit.
    score += (post_residual as f64).powf(1.2) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #1173: Adaptive Best-Fit-Decreasing with Lookahead Penalty.
    // The objective is to minimize post_residual (Best Fit) while penalizing 
    // the creation of "orphan" space that cannot accommodate the next_item_size.

    let mut score = post_residual as f64;

    // 1. Penalize creating a new bin unless the current open bins are too full to accommodate future items.
    // If the bin is new, we add a penalty based on the current number of open bins.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 2. Lookahead Penalty: If the post_residual is smaller than the next_item_size, 
    // we effectively "waste" the remaining space. We penalize this waste.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward bins that leave exactly enough room for the next item (perfect match).
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs()) * 0.1;
        }
    }

    // 3. Global State Balancing: If the current bin's residual is significantly lower than 
    // the mean_residual, it is a "tight" bin. We reward filling tight bins to avoid 
    // leaving many bins with small, unusable scraps.
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.8;
    }

    // 4. Scarcity adjustment: If this is the last fitting bin, prioritize it to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the smallest post-residual (minimizing wasted space).
    // The base score (post_residual) already incentivizes this.

    // 2. Lookahead optimization (k=2):
    // If the next item fits into the current post_residual, drastically lower the score.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 45.0;
    }

    // 3. Penalty for "Dead Zones":
    // If post_residual is in the range (0, 10), it is too small for any item (min size 10).
    // This creates "fragmentation" which we should heavily penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // 4. Scarcity and Progression:
    // As the stream nears the end (step_index / total_items -> 1), be more conservative 
    // about opening new bins. If this is a new bin (bin_residual == bin_capacity),
    // penalize it more as we approach the end of the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 25.0 * progress;

        // If we have other bins that can fit the item, strongly discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // 5. Global state balancing:
    // If the average residual of open bins is high, we have capacity; favor utilizing 
    // existing bins over new ones.
    if mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Penalize creating tiny slivers (dead space) that are hard to fill later
    // An ideal fit is 0, but if we can't hit 0, we prefer larger remainders 
    // that might accommodate future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Lookahead logic: if the next item can fit in this post_residual, 
    // heavily incentivize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // Dynamic pressure: as the stream progresses, prioritize closing bins 
    // (lower mean_residual) to reduce the number of active open bins.
    let closure_pressure = (open_bins_count as f64 / 10.0) * progress;
    score += closure_pressure * (post_residual as f64 / bin_capacity as f64);

    // If this is the only bin that can fit the item, we are forced to use it.
    // We lower the score to make it the default choice.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalty for opening a new bin: only do it if existing bins provide 
    // poor fit (high post_residual).
    if bin_residual == bin_capacity {
        score += 40.0 + (progress * 30.0);
    }

    // Adjust score based on how much this specific bin deviates from the average.
    // We prefer bins that are 'denser' than the current mean.
    if (bin_capacity - bin_residual) > (bin_capacity as f64 - mean_residual) as u32 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // We treat post_residual as the base cost.

    // 2. Lookahead optimization: If next_item_size can fit into the new post_residual,
    // we reward this placement heavily to minimize future fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Harmonic class awareness: 
    // If post_residual is small but > 0, it creates "unusable" space for large items.
    // We penalize "sliver" spaces (e.g., 1-9) unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Pressure management:
    // If we have few fitting bins, we are desperate. If many, we can be picky.
    // If fitting_bins_count is 1, this is the only bin that can take it, so we discount its penalty.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // 5. New Bin logic:
    // Only open a new bin if the current bin is "bad" for the item or future items.
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have many open bins already or if 
        // the current item is very large (forcing a poor fit elsewhere).
        if open_bins_count > 5 || item_size > 70 {
            score = 40.0;
        } else {
            score = 100.0; // High penalty to discourage opening new bins prematurely
        }
    }

    // 6. Global density balance:
    // If the average residual is high, we are under-utilizing bins. 
    // Reward placements that bring the bin closer to the mean.
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // If post_residual is between 1 and 9, it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Heuristic: Prefer filling bins that are already closer to capacity (Best Fit).
    // Subtracting based on how full the bin becomes.
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    // Lookahead logic: If next_item_size is large, favor bins that can accommodate it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Pressure to minimize open_bins_count: 
    // Discourage opening a new bin (where bin_residual == bin_capacity) 
    // unless the fit is extremely poor in all existing bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 5.0) + (1.0 - (step_index as f64 / total_items as f64)) * 10.0;
    }

    // If this is the last chance to fit the item in an existing bin, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize high mean_residual: encourages packing bins tighter globally.
    score += mean_residual * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Aggressive 2-step lookahead matching
    // Objective: Minimize post_residual, but heavily penalize bins that leave 
    // "unusable" space (e.g., < 10) unless it perfectly fits the next item.

    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead zones" (1..9) which are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead optimization: Reward bins that become perfect fits for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            // Slight reward for leaving enough room for next_item_size
            score -= 5.0;
        }
    }

    // 3. Global awareness: If this is the only bin that fits, prioritize it unless 
    // it's a terrible fit (very high post_residual).
    if fitting_bins_count == 1 && post_residual < 20 {
        score -= 20.0;
    }

    // 4. Density balancing: Penalize opening a new bin if the mean_residual is already high.
    // This forces the algorithm to consolidate items into existing bins.
    if bin_residual == bin_capacity {
        score += mean_residual * 0.5;
        // Discourage opening new bins early in the stream
        score += (1.0 - (step_index as f64 / total_items as f64)) * 10.0;
    }

    // 5. Final adjustment: Prefer tighter fits (lower post_residual)
    score += (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Current progress factor [0.0, 1.0]
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post-placement residual (Best Fit logic)
    let mut score = post_residual as f64;

    // Penalty for creating "dead zones" (small residuals that are hard to fill)
    // Residuals between 1 and 9 are extremely difficult to fill given the input range
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 + (post_residual as f64 * 2.0);
    }

    // Lookahead logic: if next item exists, reward bins that can accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong incentive to keep space for the next item
            score -= 25.0;
        } else {
            // Penalty for stranding the next item
            score += 15.0;
        }
    }

    // Dynamic thresholding: as we reach the end of the stream, prioritize packing tightly
    // to avoid opening new bins unnecessarily.
    if fitting_bins_count > 0 && bin_residual != bin_capacity {
        // If this bin is the only one left that fits, prioritize it heavily
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // New bin logic: only open a new bin if the current fit is extremely poor
    // or if we are very early in the stream and want to keep bins "open" for better future fits.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 35.0;
        // Reduce new bin penalty if existing bins are already very full (high utilization)
        if mean_residual < 20.0 {
            score -= 10.0;
        }
        // Increase penalty as we near the end of the stream
        score += progress * 20.0;
    }

    // Soft constraint: favor bins that remain near the mean residual to maintain uniform packing
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger post_residual (Best Fit principle)
    // We add a non-linear penalty for creating small, unusable gaps (1..10)
    let fragmentation_penalty = if post > 0.0 && post < 10.0 {
        100.0 / (post + 1.0)
    } else {
        0.0
    };

    // Interaction term: If we are late in the stream, be more conservative about 
    // leaving space. If fitting_bins_count is 1, avoid opening a new bin at all costs.
    let scarcity_factor = if fitting_bins_count == 1 { -500.0 } else { 0.0 };

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it 
    // (bins with higher post_residual).
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.0
    } else {
        0.0
    };

    // New bin logic: Only open a new bin if the residual is very high or forced.
    // We use a non-linear growth based on progress to discourage opening new bins 
    // too early in the stream.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_bias = if is_new_bin {
        25.0 + (progress * 50.0)
    } else {
        0.0
    };

    let score = post + fragmentation_penalty + lookahead_penalty + new_bin_bias + scarcity_factor;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating a "sliver": space too small for the smallest expected items (approx 10-15)
    // if the post_residual is in the 1..15 range, it's often better to start a new bin
    if post_residual > 0 && post_residual < 15 {
        score += 40.0 * (15.0 - post_residual as f64) / 15.0;
    }

    // Lookahead logic: if the next item can fit in the current post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Harmonic Class Logic: Prefer bins that leave a residual which is a multiple of larger item sizes
    // This reduces fragmentation by aligning potential future fits
    let harmonic_penalty = (post_residual % 20) as f64;
    score += harmonic_penalty * 0.5;

    // Favor bins that are already "fuller" (lower mean_residual) to keep open_bins_count low
    // We normalize against the capacity
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // Threshold for opening a new bin: if fitting_bins_count is low and post_residual is poor,
    // penalize the choice of an existing bin to force a new bin start if it's cleaner.
    if fitting_bins_count == 1 && post_residual > 20 {
        score += 10.0;
    }

    // Progress scaling: As we approach the end of the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // New bin penalty increases as we run out of items to minimize total bins
        score += 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
