    // 2. Open Bins Pressure: Penalize opening new bins when existing ones can accommodate the item.
    // If bin_residual == bin_capacity, we are evaluating the "Open New Bin" option.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other bins are available.
            score += 200.0 + (open_bins_count as f64 * 2.0);
