    } else {
        // 3. Lookahead Logic: If the next item is large, favor keeping space open for it.
        // If the current post_residual is smaller than the next item, it creates a fragmented bin.
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // 4. Global Efficiency: If the bin is nearly full, reward it (Best Fit variant).
    // This encourages "tight" packing to keep the mean_residual low.
    if post_residual < 5 {
        score -= 10.0;
    }

    // 5. Progression adjustment: As the stream nears the end, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin if other options exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
