    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Matching: If next_item_size fits in the post_residual, 
    // significantly reward this bin to create a "perfect pair"
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Mean-Residual Balancing:
    // If this bin's post_residual is significantly worse than the current mean, 
