}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Strategy: Balance Best-Fit (minimizing post_residual) with a penalty for creating 
    // "orphaned" space that cannot accommodate the next item (lookahead).

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post-placement residual (Best-Fit principle).
    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin prematurely.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if other options exist, 
            // scaled by how much capacity is available elsewhere.
            score += 150.0 + (mean_residual * 2.0);
        } else {
            // Necessary evil: if no bins fit, we must open a new one.
            score -= 50.0;
        }
    } else {
        // 2. Lookahead mechanism: Penalize post_residuals that are too small to fit the next item.
        if next_item_size > 0 && post_residual < next_item_size {
