    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high, reduces slightly as stream progresses 
        // to avoid being stuck with many half-empty bins at the end.
        score += 40.0 * (1.0 - (progress * 0.5));
    } else {
        // Reward bins that have low residuals
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;
    }

    // If this is the last chance to fit the item in an existing bin, reduce penalty
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
