    // Gaps < 10 are generally difficult to fill, so we treat them as high-cost.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Lookahead Synergy: If the post_residual can accommodate the next item, 
    // heavily reward this bin to keep the packing tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further refine: reward bins that leave the smallest gap after the next item.
        score -= (100.0 - (post_residual - next_item_size) as f64) * 0.1;
    }

    // 3. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless there are no other good fits available.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we are late in the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 4. Global Balance: If the current bin's residual is significantly lower than 
    // the mean_residual of other bins, it's a "tight" bin. We prioritize 
    // filling tight bins to keep the average residual high for future items.
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // 5. Urgency: If this is the only bin that can fit the item, prioritize it 
    // to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
