    // Favor bins that align with the global mean residual to keep packing density uniform.
    let deviation_penalty = (post - mean_residual).abs() * 0.5;

    // Final score: minimize this value.
    // We prioritize small post_residual (Best Fit) but modulate with lookahead and progress.
    post + dead_space_penalty + lookahead_penalty + new_bin_penalty + deviation_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

