    // 2. Harmonic Class Logic: Favor filling bins to specific capacity tiers.
    // We reward post_residuals that are multiples of 25 (e.g., 0, 25, 50), 
    // as these are more likely to accommodate future items (10-80 range).
    let harmonic_mod = post_residual % 25;
    score += (harmonic_mod as f64) * 0.8;

    // 3. Lookahead Integration: If next_item_size is large, prioritize bins 
    // that leave enough room for it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that cannot fit the next expected item.
            score += 35.0;
        } else {
            // Reward bins that leave exactly enough room for the next item (tight fit).
            let slack = post_residual - next_item_size;
            score += (slack as f64) * 0.2;
        }
    }

    // 4. Global State Optimization: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless fitting_bins_count is 0 (meaning we have no choice).
    if bin_residual == bin_capacity {
