    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Dynamic Thresholding: As the stream progresses, become more conservative about opening new bins.
    // When residual is bin_capacity, we are evaluating a "New Bin" option.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin if we have many fitting bins available.
        score += 15.0 * (fitting_bins_count as f64).sqrt();
        // Penalize opening a new bin as we near the end of the stream to force consolidation.
        score += 30.0 * progress;
    } else {
        // 4. Global State Awareness: If the current bin's residual is significantly better than the mean,
        // prioritize keeping it balanced.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }

        // If this is the last chance to fit the item in an existing bin, favor it to avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 5. Large Item Handling: If the item is large, favor bins that result in a perfectly filled bin (0 residual).
    if item_size > 70 && post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize tighter fits (lower post_residual).
    // We use a quadratic penalty for post_residual to discourage wasted space.
    let mut score = (post_residual as f64).powi(2);

    // If this is a new bin, penalize based on current progress and number of open bins.
    // As the stream progresses, we want to be more conservative about opening new bins.
    if is_new_bin {
        // Penalty for opening a new bin is higher if we have many empty bins or late in the stream.
        score += (bin_capacity as f64) * (1.0 + progress * 2.0 + (open_bins_count as f64).sqrt());
    } else {
        // Reward bins that are "almost full" (low post_residual) more aggressively if 
        // the next item is large, to preserve space for future items.
        if next_item_size > 0 {
            let next_item_penalty = if (post_residual as u32) < next_item_size {
                // Future item won't fit here; this is a "dead space" trap.
                (next_item_size - post_residual) as f64 * 1.5
            } else {
                // Future item fits; reward this placement.
                -(next_item_size as f64) * 0.5
            };
            score += next_item_penalty;
        }

        // Encourage leveling out residuals across open bins to prevent isolated high-residual bins.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Adjust for the exclusivity of the bin (if it's the only one that fits, prioritize it).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= (bin_capacity - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (residuals < 10) that cannot fit any item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Harmonic Class Logic: Prefer residuals that are multiples of larger items.
    // If post_residual is a multiple of 20, it is more likely to accommodate future items.
    if post_residual % 20 == 0 {
