    }

    // 5. New Bin Thresholding: Discourage opening a new bin unless the current mean residual is low,
    // indicating that existing bins are already too crowded to be useful for future items.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 30.0 {
            score += 100.0;
        } else {
            score += 20.0;
        }
    }

    // 6. Dynamic Scaling: As the stream progresses, favor tighter packing to clear out open bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
