    // "unusable" gaps (1-9) that cannot fit the smallest possible items.

    let mut score = post_residual as f64;

    // Penalty for creating a 'sliver' (dead space 1..9)
    // Small gaps are highly likely to remain empty for the rest of the stream.
    if post_residual > 0 && post_residual < 10 {
