        ((post_res - next_item_size as f64).abs()).powf(1.2)
    } else {
        post_res * 0.1
    };

    // Penalize creation of "sliver" space (small, unusable residuals)
    // Non-linear penalty for residuals between 1 and 9
    let sliver_penalty = if post_res > 0.0 && post_res < 10.0 {
