    let load_balance = (post_res - mean_residual).powf(2.0) * 0.1;

    // Favor bins that are "tight" but not too tight, scaled by the remaining stream
    let tightness_bonus = (post_res / bin_capacity as f64) * (1.0 - progress) * 10.0;

    let mut score = post_res + new_bin_penalty + sliver_penalty + load_balance - tightness_bonus + lookahead_alignment;

