            score += 150.0 + (progress * 50.0);
        } else {
            // Must open a new bin, normalize score relative to potential capacity
            score = 50.0;
        }
    } else {
        // Lookahead heuristic: Favor bins where the post_residual is close to the next_item_size
        // This promotes "perfect fit" chains
        if next_item_size > 0 {
            let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
            score += diff * 0.8;
        }

        // Penalty for creating "fragmented" space (residuals smaller than typical items)
        if post_residual < 20 && post_residual > 0 {
