    // 2. Lookahead Synergy: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is extremely tight (Best Fit).
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many bins are already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // If we have many open bins, we should favor filling existing ones over starting new ones.
    }

    // 4. Fitting Constraint: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Mean Residual Balancing: Avoid creating bins that deviate significantly from the current average
    // to keep the bin landscape uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Progress Scaling: As we approach the end of the stream, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Archetype: Aggressive Best-Fit with Lookahead and Residual Balancing.

    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space": if the post_residual is too small to fit common items,
    // it's often better to have used a different bin.
    if post_residual > 0 && post_residual < 10 {
