        if fitting_bins_count > 0 {
            score += 65.0; 
        } else {
            score -= 10.0;
        }
    }

    // 4. Residual Balancing: If this bin's residual is significantly lower than the mean_residual
    // of other bins, we prefer to keep it "tight" (Best Fit).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Progression Scaling: As we approach the end of the stream, be more conservative
