        // If it's an existing bin, favor those that move the mean_residual closer to 
        // the average item size (heuristically ~30-40) to keep bins balanced.
        let deviation = (post_residual as f64 - 35.0).abs();
        score += deviation * 0.1;
    }

    // 4. Scarcity handling: If only one bin can fit the item, prioritize it to avoid 
    // fragmenting the bin count unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Dynamic horizon: As the stream nears the end, prioritize closing bins (lower residual).
    if progress > 0.8 {
        score -= (100 - post_residual) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny, unusable gaps that are smaller than the smallest likely future items.
    // As progress increases, we become more conservative about creating new small gaps.
    let gap_penalty = if post_res > 0.0 && post_res < 15.0 {
        (15.0 - post_res) * (1.0 + progress * 2.0)
    } else {
        0.0
    };

    // Reward bins that consolidate residual space to be closer to the mean_residual,
    // reducing variance in bin fullness which helps keep future fitting options open.
    let variance_penalty = (post_res - mean_residual).abs() * 0.5;

    // Lookahead: If the next item exists, penalize bins that cannot fit it after this placement.
    let lookahead_penalty = if next_item_size > 0 && (post_res < next_item_size as f64) {
        10.0 * (1.0 - progress)
    } else {
        0.0
    };

    // New bin bias: If this is an empty bin, we only prefer it if we are early in the stream
    // or if the current open bins are extremely inefficient (high mean_residual).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_bias = if is_new_bin {
        // High penalty to prevent opening new bins unnecessarily late in the stream
        35.0 + (progress * 50.0) + (mean_residual * 0.2)
    } else {
        0.0
    };

    // Fitting constraint: If this is the only bin that can fit the item, give it a massive boost.
    let urgency_bonus = if fitting_bins_count == 1 && !is_new_bin {
        -50.0
    } else {
        0.0
    };

    // Final score: Minimize residual (Best Fit), modulated by penalty terms.
    post_res + gap_penalty + variance_penalty + lookahead_penalty + new_bin_bias + urgency_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

