    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Dynamic balancing:
    // Penalize creating bins with high residuals relative to the mean_residual
    // to keep the bin distribution uniform.
    let residual_penalty = (post_residual as f64 - mean_residual).powi(2) * 0.05;
    score += residual_penalty;

    // Favor filling bins closer to capacity (non-linear curve)
    score += (post_residual as f64).powf(1.5) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily favor small residuals (Best Fit)
    // 2. Penalty for creating "dead space": small residuals that cannot fit common item sizes (10-30)
    if post_residual > 0 && post_residual < 10 {
