    if next_item_size > 0 {
        let fits_next = post_residual >= next_item_size;
        if !fits_next && post_res > 0.0 {
            // Penalize using a bin that cannot take the next item if we are mid-stream.
            score += (1.0 - progress) * 10.0;
        }
    }

    // Dynamic threshold: As we approach the end of the stream, prioritize closing bins
    // by heavily penalizing new bin creation (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // The cost of opening a new bin increases as we progress through the stream,
