        let open_cost = 20.0 + (progress * 50.0);
        score += open_cost;

        // If there are other bins that could fit this item, make the new bin very unattractive.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // Coupling with global state: if mean_residual is low, we are already packing tightly.
    // Penalize placements that increase the deviation from an ideal compact state.
    score += (post_res - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
