    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize small gaps that are unlikely to fit future items.
    // If post_residual is < 10, it is likely "trapped" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - (diff / 100.0));
    }

    // 3. Open Bin Pressure: Discourage opening new bins (bin_residual == bin_capacity)
    // unless the current available space creates a very poor fit.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 0.5);
    }

    // 4. Fitting Scarcity: If this is the only bin that can fit the item, favor it to avoid
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global Efficiency: If the current bin is significantly worse than the mean, penalize it.
    if (post_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Archetype: Aggressive 2-step lookahead matching.
    // Goal: Minimize post_residual, but prioritize bins where post_residual perfectly matches next_item_size.
    // Penalize opening new bins unless the current options are extremely poor.

    let mut score = post_residual as f64;

    // 1. Reward the "Perfect Fit" for current item
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2. Lookahead: Reward if post_residual fits the next item perfectly
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        if diff == 0.0 {
            score -= 60.0; // Strongest incentive for Best-Fit-Lookahead
        } else {
            // Otherwise, favor bins that leave just enough space for the next item
            score += diff * 0.5;
        }
    }

    // 3. Penalty for "Wasted Space" relative to global state
    // If we leave a gap smaller than the smallest likely item (10), it's dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. Heuristic for New Bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already (to keep density high)
        // or if fitting_bins_count is 0 (forced).
        if fitting_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0; // Forced, make it attractive
        }
    }

    // 5. Global density balancing
    // If the current bin's residual is significantly higher than the mean_residual, 
    // it is a "loose" bin; discourage filling it further if better options exist.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-residual space (Best Fit variant).
    // Smaller post_residual is usually better (tighter packing).
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to be filled.
    // If post_residual is < 10, it's effectively unusable for most items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: If we can fit the next item into this bin, reward that placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Penalty for opening a new bin prematurely.
    if is_new_bin {
        // If there are bins that could fit this, heavily discourage opening a new one
        // unless the mean residual is already quite low (suggesting we need fresh space).
        if fitting_bins_count > 0 {
            score += 60.0 * (1.0 - (mean_residual / bin_capacity as f64));
        }
        // As we approach the end of the stream, opening a new bin is increasingly costly.
        score += 50.0 * progress;
    } else {
        // Reward utilizing existing bins to keep open_bins_count low.
        score -= 5.0 * (open_bins_count as f64).sqrt();
    }

    // Adjust for global packing density: if the mean residual is high, 
    // we have plenty of room, so favor tighter fits to consolidate.
    if mean_residual > 30.0 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: non-linear growth as the stream progresses
    // We penalize new bins more heavily towards the end of the stream to force consolidation
    if is_new_bin {
        score += 25.0 + (progress * 40.0).powf(1.5);
    } else {
        // Reward bins that are "almost full" relative to the lookahead
        // If the next item fits into the post_residual, we reward this bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }

        // Penalize fragmentation: if this bin becomes very difficult to fill (small residual)
        // but only if we have other bins available.
        if post_residual > 0 && post_residual < 15 {
            score += 12.0 * (1.0 - progress);
        }
    }

    // Coupling: If this is the last fitting bin, prioritize it to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Smoothing: adjust based on deviation from the mean_residual of open bins
    // This encourages keeping the fill-level of bins consistent (Best Fit Decreasing style)
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * deviation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize minimizing the post_residual (tightest fit).
    // The base score is already post_residual.

    // 2. Lookahead Synergy: If next_item_size is non-zero, favor bins that can accommodate it.
    // If post_residual is small but leaves enough for the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Penalty for "Wasted Potential": If post_residual is small but unusable (e.g., < 10),
    // it creates "dead space" that likely won't be filled by future items.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // 4. Harmonic Thresholding: Penalize bins that deviate significantly from the mean_residual
    // to keep bin utilization balanced.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // 5. New Bin Penalty: Discourage opening a new bin unless the current fit is terrible.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if existing ones can fit the item
            score += 60.0;
        } else {
            // Necessary to open a new bin, neutralize the penalty
            score = 25.0;
        }
    }

    // 6. Progressive Consolidation: As the stream nears completion, favor filling existing bins
    // aggressively to avoid leaving partially filled bins at the end of the stream.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize small gaps that are hard to fill (1..9).
    // These gaps are "orphaned" because the minimum item size is effectively 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual,
    // lower the score to prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Fragmentation Control: If this is the last bin that can fit the item,
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // 4. Open Bin Pressure: Penalize opening new bins as the stream progresses.
    // If this is a new bin (bin_residual == bin_capacity), increase the cost.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // As the stream progresses, opening a new bin becomes increasingly expensive.
        score += 25.0 + (progress * 20.0);

        // If we already have many open bins, penalize opening another one.
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Global Balance: Favor bins that keep the mean residual of all bins high,
    // to keep capacity available for larger items later.
    if post_residual < (mean_residual as u32) {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin unless absolutely necessary
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 200.0; // Strong penalty for opening a new bin if space exists
        } else {
            score -= 50.0; // Reward opening a new bin if no other choice
        }
    }

    // 2. Lookahead matching: reward bins where the post_residual is close to next_item_size
    // This minimizes fragmentation by creating a "perfect fit" for the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;
    }

    // 3. Fragmentation control: penalize leaving small gaps that are likely useless (under 10)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. Balance: favor bins that remain closer to the global mean_residual to keep load balanced
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.2;

    // 5. Urgency: if this is the last fitting bin, prioritize it to save space for future items
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progress scaling: as we near the end of the stream, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}
